// Tajwīd: makhārij al-ḥurūf, ṣifāt al-ḥurūf, strong and weak letters, waqf and ibtidāʾ, muṣḥaf stop signs, stopping on word endings, with verse spotting. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  // ---------- Makhārij al-ḥurūf ----------
  { id: "tjm-001", s: "tajweed", g: 1, d: 1, t: ["makharij", "makharij-areas"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["Into how many main areas (mawāḍiʿ) are the points of articulation of the Arabic letters grouped?", ["Five", "Three", "Seven", "Four"], "The five areas are the oral and throat cavity (jawf), the throat (ḥalq), the tongue (lisān), the lips (shafatān) and the nasal cavity (khayshūm). The individual makhārij are distributed across these five."],
    de: ["In wie viele Hauptbereiche (Mawāḍiʿ) werden die Artikulationsstellen der arabischen Buchstaben eingeteilt?", ["Fünf", "Drei", "Sieben", "Vier"], "Die fünf Bereiche sind der Mund- und Rachenhohlraum (Ǧauf), die Kehle (Ḥalq), die Zunge (Lisān), die Lippen (Šafatān) und die Nasenhöhle (Ḫayšūm). Auf sie verteilen sich die einzelnen Maḫāriǧ."],
    ar: ["كم عددُ المواضع الرئيسة التي تُجمع فيها مخارج الحروف العربية؟", ["خمسة", "ثلاثة", "سبعة", "أربعة"], "المواضع الخمسة هي: الجوف، والحلق، واللسان، والشفتان، والخيشوم، وتتوزع عليها المخارج التفصيلية."] },

  { id: "tjm-002", s: "tajweed", g: 1, d: 1, t: ["makharij", "makharij-halq"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["From which of the five areas do hamza, hāʾ, ʿayn, ḥāʾ, ghayn and khāʾ originate?", ["The throat (ḥalq)", "The tongue (lisān)", "The jawf", "The nasal cavity (khayshūm)"], "These six are the throat letters (ḥurūf ḥalqiyya). They come from three points of the throat: the deepest part, the middle and the part nearest the mouth."],
    de: ["Aus welchem der fünf Bereiche stammen Hamza, Hāʾ, ʿAin, Ḥāʾ, Ġain und Ḫāʾ?", ["Aus der Kehle (Ḥalq)", "Aus der Zunge (Lisān)", "Aus dem Ǧauf", "Aus der Nasenhöhle (Ḫayšūm)"], "Diese sechs sind die Kehlbuchstaben (Ḥurūf ḥalqiyya). Sie kommen aus drei Stellen der Kehle: dem tiefsten Teil, der Mitte und dem Teil, der dem Mund am nächsten liegt."],
    ar: ["من أيِّ المواضع الخمسة تخرج الهمزة والهاء والعين والحاء والغين والخاء؟", ["من الحلق", "من اللسان", "من الجوف", "من الخيشوم"], "هذه الستة هي الحروف الحلقية، وتخرج من ثلاثة مخارج في الحلق: أقصاه ووسطه وأدناه."] },

  { id: "tjm-003", s: "tajweed", g: 1, d: 2, t: ["makharij", "makharij-count"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, opening verses on makhārij",
    en: ["According to the view adopted by Ibn al-Jazarī in his Muqaddima, how many specific makhārij do the letters have?", ["Seventeen", "Sixteen", "Fourteen", "Twenty-nine"], "Ibn al-Jazarī follows al-Khalīl and most reciters in counting seventeen makhārij. Sixteen and fourteen are the counts of other grammarians; twenty-nine is the number of letters, not of makhārij."],
    de: ["Wie viele einzelne Maḫāriǧ haben die Buchstaben nach der Auffassung, die Ibn al-Ǧazarī in seiner Muqaddima vertritt?", ["Siebzehn", "Sechzehn", "Vierzehn", "Neunundzwanzig"], "Ibn al-Ǧazarī folgt al-Ḫalīl und den meisten Rezitatoren und zählt siebzehn Maḫāriǧ. Sechzehn und vierzehn sind Zählungen anderer Grammatiker; neunundzwanzig ist die Zahl der Buchstaben, nicht der Maḫāriǧ."],
    ar: ["كم عددُ المخارج التفصيلية للحروف على المذهب الذي اختاره ابن الجزري في مقدمته؟", ["سبعة عشر", "ستة عشر", "أربعة عشر", "تسعة وعشرون"], "اختار ابن الجزري مذهب الخليل وأكثر القراء أن المخارج سبعة عشر. أما ستة عشر وأربعة عشر فمذهبا غيرهم من النحاة، وتسعة وعشرون عدد الحروف لا المخارج."] },

  { id: "tjm-004", s: "tajweed", g: 4, d: 4, t: ["makharij", "makharij-count", "jawf"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on makhārij al-ḥurūf; Sībawayh, al-Kitāb, ch. on idghām",
    en: ["Sībawayh counted sixteen makhārij instead of seventeen. Which area did he not count as a separate makhraj?", ["The jawf: he placed alif with the deepest throat and the madd wāw and yāʾ with their non-madd counterparts", "The khayshūm: he treated the ghunna as an attribute of nūn and mīm only", "The lips: he joined fāʾ with the makhraj of the dental letters", "The deepest throat: he joined hamza and hāʾ with ʿayn and ḥāʾ"], "Sībawayh and those who followed him dropped the jawf. He assigned alif to the deepest part of the throat together with hamza and hāʾ, the madd wāw to the lips and the madd yāʾ to the middle of the tongue."],
    de: ["Sībawaih zählte sechzehn statt siebzehn Maḫāriǧ. Welchen Bereich zählte er nicht als eigene Artikulationsstelle?", ["Den Ǧauf: Er ordnete Alif dem tiefsten Teil der Kehle und das Madd-Wāw und -Yāʾ ihren Nicht-Madd-Entsprechungen zu", "Den Ḫayšūm: Er behandelte die Ghunna nur als Eigenschaft von Nūn und Mīm", "Die Lippen: Er legte Fāʾ mit der Stelle der Zahnbuchstaben zusammen", "Den tiefsten Teil der Kehle: Er legte Hamza und Hāʾ mit ʿAin und Ḥāʾ zusammen"], "Sībawaih und seine Nachfolger ließen den Ǧauf weg. Alif ordnete er mit Hamza und Hāʾ dem tiefsten Teil der Kehle zu, das Madd-Wāw den Lippen und das Madd-Yāʾ der Zungenmitte."],
    ar: ["عدَّ سيبويه المخارج ستة عشر لا سبعة عشر. فأيَّ موضع لم يجعله مخرجًا مستقلًّا؟", ["الجوف؛ إذ جعل الألف مع أقصى الحلق، والواو والياء المديتين مع غير المديتين", "الخيشوم؛ إذ جعل الغنة صفةً للنون والميم فحسب", "الشفتين؛ إذ ضمَّ الفاء إلى مخرج الحروف الأسنانية", "أقصى الحلق؛ إذ ضمَّ الهمزة والهاء إلى العين والحاء"], "أسقط سيبويه ومن تبعه مخرج الجوف، فجعل الألف من أقصى الحلق مع الهمزة والهاء، والواو المدية من الشفتين، والياء المدية من وسط اللسان."] },

  { id: "tjm-005", s: "tajweed", g: 4, d: 5, t: ["makharij", "makharij-count", "makharij-lisan"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on makhārij al-ḥurūf",
    en: ["Which grammarian is best known for counting only fourteen makhārij by giving lām, nūn and rāʾ a single makhraj?", ["al-Farrāʾ", "Sībawayh", "al-Khalīl ibn Aḥmad", "Makkī ibn Abī Ṭālib"], "Ibn al-Jazarī reports that al-Farrāʾ, with Quṭrub, al-Jarmī and Ibn Kaysān, counted fourteen by merging the makhārij of lām, nūn and rāʾ. Sībawayh counted sixteen and al-Khalīl seventeen."],
    de: ["Welcher Grammatiker ist dafür bekannt, nur vierzehn Maḫāriǧ zu zählen, indem er Lām, Nūn und Rāʾ eine gemeinsame Stelle gab?", ["al-Farrāʾ", "Sībawaih", "al-Ḫalīl ibn Aḥmad", "Makkī ibn Abī Ṭālib"], "Ibn al-Ǧazarī berichtet, dass al-Farrāʾ, zusammen mit Quṭrub, al-Ǧarmī und Ibn Kaisān, vierzehn zählte, indem er die Stellen von Lām, Nūn und Rāʾ zusammenlegte. Sībawaih zählte sechzehn, al-Ḫalīl siebzehn."],
    ar: ["مَن أشهرُ مَن عدَّ المخارج أربعة عشر بجعل اللام والنون والراء من مخرج واحد؟", ["الفراء", "سيبويه", "الخليل بن أحمد", "مكي بن أبي طالب"], "ذكر ابن الجزري أن الفراء ومعه قطرب والجرمي وابن كيسان عدُّوها أربعة عشر بجعل اللام والنون والراء من مخرج واحد، وعدَّها سيبويه ستة عشر، والخليل سبعة عشر."] },

  { id: "tjm-006", s: "tajweed", g: 1, d: 1, t: ["makharij", "jawf"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["Which letters are pronounced from the jawf (the empty space of the mouth and throat)?", ["Alif, and wāw and yāʾ when they are madd letters", "Hamza, hāʾ and ʿayn", "Mīm and nūn with their ghunna", "Fāʾ, bāʾ and mīm"], "The jawf letters are the three madd letters: alif, wāw sākina after ḍamma and yāʾ sākina after kasra. Their sound ends when the air ends, not at a fixed point."],
    de: ["Welche Buchstaben werden aus dem Ǧauf (dem Hohlraum von Mund und Rachen) gesprochen?", ["Alif sowie Wāw und Yāʾ, wenn sie Dehnungsbuchstaben sind", "Hamza, Hāʾ und ʿAin", "Mīm und Nūn mit ihrer Ghunna", "Fāʾ, Bāʾ und Mīm"], "Die Ǧauf-Buchstaben sind die drei Dehnungsbuchstaben: Alif, Wāw sākina nach Ḍamma und Yāʾ sākina nach Kasra. Ihr Laut endet mit dem Ende des Luftstroms, nicht an einem festen Punkt."],
    ar: ["ما الحروف التي تخرج من الجوف؟", ["الألف، والواو والياء إذا كانتا حرفي مد", "الهمزة والهاء والعين", "الميم والنون بغنتهما", "الفاء والباء والميم"], "حروف الجوف هي حروف المد الثلاثة: الألف، والواو الساكنة المضموم ما قبلها، والياء الساكنة المكسور ما قبلها، وينقطع صوتها بانقطاع الهواء."] },

  { id: "tjm-007", s: "tajweed", g: 3, d: 4, t: ["makharij", "jawf"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on makhārij al-ḥurūf",
    en: ["Why is the makhraj of the jawf letters called muqaddar (estimated) rather than muḥaqqaq (fixed)?", ["Their sound does not stop at a specific point of the mouth or throat but ends with the end of the air", "They are only written in the muṣḥaf and are not pronounced at all", "Their makhraj changes according to the vowel of the next word", "They come from the nose and therefore have no point inside the mouth"], "A muḥaqqaq makhraj is a definite point where the sound is cut, such as the lips for bāʾ. The madd letters have no such point: they run through the cavity of mouth and throat and stop when the breath stops."],
    de: ["Warum nennt man die Artikulationsstelle der Ǧauf-Buchstaben muqaddar (geschätzt) und nicht muḥaqqaq (fest)?", ["Ihr Laut endet nicht an einem bestimmten Punkt in Mund oder Kehle, sondern mit dem Ende des Luftstroms", "Sie werden nur im Muṣḥaf geschrieben und gar nicht ausgesprochen", "Ihre Stelle ändert sich je nach Vokal des folgenden Wortes", "Sie kommen aus der Nase und haben daher keinen Punkt im Mund"], "Eine feste Stelle ist ein bestimmter Punkt, an dem der Laut abbricht, etwa die Lippen beim Bāʾ. Die Dehnungsbuchstaben haben keinen solchen Punkt: Sie laufen durch den Hohlraum von Mund und Rachen und enden mit dem Atem."],
    ar: ["لماذا يُسمّى مخرج حروف الجوف مقدَّرًا لا محقَّقًا؟", ["لأن صوتها لا ينقطع عند موضع معيّن من الفم أو الحلق، بل ينتهي بانتهاء الهواء", "لأنها تُكتب في المصحف ولا تُنطق أصلًا", "لأن مخرجها يتغير بحسب حركة الكلمة التالية", "لأنها تخرج من الأنف فلا موضع لها في الفم"], "المخرج المحقَّق موضع معيّن ينقطع عنده الصوت كالشفتين للباء، أما حروف المد فتجري في فراغ الفم والحلق وتنتهي بانتهاء النفس، فمخرجها مقدَّر."] },

  { id: "tjm-008", s: "tajweed", g: 2, d: 2, t: ["makharij", "makharij-method"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on makhārij al-ḥurūf",
    en: ["What method does Ibn al-Jazarī describe for finding the makhraj of a letter?", ["Pronounce it sākin or doubled after a voweled hamza and note where the sound stops", "Pronounce it with fatḥa and lengthen the vowel for two counts", "Pronounce it with tanwīn and observe whether air leaves the nose", "Say the letter's name and note where its last sound is produced"], "Ibn al-Jazarī says: make the letter sākin or mushaddad and put a hamzat waṣl with any vowel before it, as in ab or aq; where the sound stops is its makhraj. A vowel after the letter would carry the sound away from it."],
    de: ["Welche Methode beschreibt Ibn al-Ǧazarī, um die Artikulationsstelle eines Buchstabens zu finden?", ["Ihn sākin oder verdoppelt nach einem vokalisierten Hamza sprechen und beachten, wo der Laut endet", "Ihn mit Fatḥa sprechen und den Vokal zwei Zählzeiten dehnen", "Ihn mit Tanwīn sprechen und prüfen, ob Luft aus der Nase strömt", "Den Namen des Buchstabens sagen und beachten, wo der letzte Laut entsteht"], "Ibn al-Ǧazarī sagt: Man macht den Buchstaben sākin oder verdoppelt und setzt ein Hamzat al-Waṣl mit beliebigem Vokal davor, etwa ab oder aq; wo der Laut abbricht, liegt seine Stelle. Ein Vokal nach dem Buchstaben würde den Laut von ihm wegtragen."],
    ar: ["ما الطريقة التي ذكرها ابن الجزري لمعرفة مخرج الحرف؟", ["أن يُسكَّن الحرف أو يُشدَّد وتُدخَل عليه همزة متحركة، فحيث ينقطع الصوت فهو مخرجه", "أن يُنطق مفتوحًا ويُمدّ صوته حركتين", "أن يُنطق منوّنًا ويُلاحظ خروج الهواء من الأنف", "أن يُنطق اسم الحرف ويُلاحظ موضع آخر صوت فيه"], "قال ابن الجزري: إذا أردت معرفة مخرج الحرف فسكِّنه أو شدِّده وأدخل عليه همزة الوصل بأي حركة، نحو: أَبْ، أَقْ، فحيث انقطع الصوت كان مخرجه."] },

  { id: "tjm-009", s: "tajweed", g: 1, d: 1, t: ["makharij", "makharij-halq"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["Which two letters come from the deepest part of the throat (aqṣā al-ḥalq)?", ["Hamza and hāʾ", "ʿAyn and ḥāʾ", "Ghayn and khāʾ", "Qāf and kāf"], "The deepest part of the throat, nearest the chest, produces hamza and hāʾ. ʿAyn and ḥāʾ come from the middle and ghayn and khāʾ from the part nearest the mouth."],
    de: ["Welche zwei Buchstaben kommen aus dem tiefsten Teil der Kehle (Aqṣā al-Ḥalq)?", ["Hamza und Hāʾ", "ʿAin und Ḥāʾ", "Ġain und Ḫāʾ", "Qāf und Kāf"], "Der tiefste Teil der Kehle, zur Brust hin, bildet Hamza und Hāʾ. ʿAin und Ḥāʾ kommen aus der Mitte, Ġain und Ḫāʾ aus dem Teil, der dem Mund am nächsten ist."],
    ar: ["ما الحرفان اللذان يخرجان من أقصى الحلق؟", ["الهمزة والهاء", "العين والحاء", "الغين والخاء", "القاف والكاف"], "يخرج من أقصى الحلق مما يلي الصدر الهمزة والهاء، ومن وسطه العين والحاء، ومن أدناه مما يلي الفم الغين والخاء."] },

  { id: "tjm-010", s: "tajweed", g: 1, d: 2, t: ["makharij", "makharij-halq"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["Which two letters come from the part of the throat nearest the mouth (adnā al-ḥalq)?", ["Ghayn and khāʾ", "Hamza and hāʾ", "ʿAyn and ḥāʾ", "Qāf and ghayn"], "Adnā al-ḥalq, the upper part of the throat next to the mouth, produces ghayn and khāʾ. Qāf is already a tongue letter, from the back of the tongue."],
    de: ["Welche zwei Buchstaben kommen aus dem Teil der Kehle, der dem Mund am nächsten ist (Adnā al-Ḥalq)?", ["Ġain und Ḫāʾ", "Hamza und Hāʾ", "ʿAin und Ḥāʾ", "Qāf und Ġain"], "Adnā al-Ḥalq, der obere Teil der Kehle am Mund, bildet Ġain und Ḫāʾ. Qāf ist bereits ein Zungenbuchstabe vom hinteren Teil der Zunge."],
    ar: ["ما الحرفان اللذان يخرجان من أدنى الحلق مما يلي الفم؟", ["الغين والخاء", "الهمزة والهاء", "العين والحاء", "القاف والغين"], "يخرج من أدنى الحلق الغين والخاء، أما القاف فمن أقصى اللسان لا من الحلق."] },

  { id: "tjm-011", s: "tajweed", g: 2, d: 2, t: ["makharij", "makharij-lisan"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["Which letter is produced from the furthest back part of the tongue together with the soft palate above it?", ["Qāf", "Kāf", "Jīm", "Ghayn"], "Qāf comes from aqṣā al-lisān with the soft palate above it. Kāf comes from slightly lower, nearer the mouth; ghayn is a throat letter."],
    de: ["Welcher Buchstabe entsteht am hintersten Teil der Zunge zusammen mit dem darüberliegenden weichen Gaumen?", ["Qāf", "Kāf", "Ǧīm", "Ġain"], "Qāf kommt vom hintersten Teil der Zunge mit dem weichen Gaumen darüber. Kāf liegt etwas tiefer, näher zum Mund; Ġain ist ein Kehlbuchstabe."],
    ar: ["أيُّ حرف يخرج من أقصى اللسان مع ما يحاذيه من الحنك الأعلى (اللحمي)؟", ["القاف", "الكاف", "الجيم", "الغين"], "القاف من أقصى اللسان مع ما فوقه من الحنك الأعلى، والكاف أسفل من مخرج القاف قليلًا، والغين من الحلق."] },

  { id: "tjm-012", s: "tajweed", g: 2, d: 3, t: ["makharij", "makharij-lisan"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["Which three letters come from the middle of the tongue with the hard palate above it?", ["Jīm, shīn and non-madd yāʾ", "Qāf, kāf and ghayn", "Ṭāʾ, dāl and tāʾ", "Lām, nūn and rāʾ"], "The middle of the tongue with the palate above produces jīm, shīn and the yāʾ that is not a madd letter. The madd yāʾ belongs to the jawf."],
    de: ["Welche drei Buchstaben kommen aus der Zungenmitte mit dem harten Gaumen darüber?", ["Ǧīm, Šīn und Yāʾ, wenn es kein Dehnungsbuchstabe ist", "Qāf, Kāf und Ġain", "Ṭāʾ, Dāl und Tāʾ", "Lām, Nūn und Rāʾ"], "Die Zungenmitte mit dem Gaumen darüber bildet Ǧīm, Šīn und das Yāʾ, das kein Dehnungsbuchstabe ist. Das Madd-Yāʾ gehört zum Ǧauf."],
    ar: ["ما الحروف الثلاثة التي تخرج من وسط اللسان مع ما يحاذيه من الحنك الأعلى؟", ["الجيم والشين والياء غير المدية", "القاف والكاف والغين", "الطاء والدال والتاء", "اللام والنون والراء"], "يخرج من وسط اللسان مع ما يحاذيه من الحنك الأعلى الجيم والشين والياء غير المدية، أما الياء المدية فمن الجوف."] },

  { id: "tjm-013", s: "tajweed", g: 2, d: 3, t: ["makharij", "makharij-lisan", "dad"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["What is the makhraj of ḍād?", ["One or both edges of the tongue against the upper molars", "The tip of the tongue against the tips of the upper incisors", "The middle of the tongue against the hard palate", "The back of the tongue against the soft palate"], "Ibn al-Jazarī: ḍād comes from the side of the tongue where it meets the upper molars, from the left or right side or both. The tip of the tongue with the upper incisors is the makhraj of ẓāʾ, dhāl and thāʾ."],
    de: ["Wo ist die Artikulationsstelle des Ḍād?", ["Ein oder beide Zungenränder an den oberen Backenzähnen", "Die Zungenspitze an den Spitzen der oberen Schneidezähne", "Die Zungenmitte am harten Gaumen", "Der hintere Zungenteil am weichen Gaumen"], "Ibn al-Ǧazarī: Ḍād kommt vom Zungenrand, wo er die oberen Backenzähne berührt, links, rechts oder auf beiden Seiten. Die Zungenspitze an den oberen Schneidezähnen ist die Stelle von Ẓāʾ, Ḏāl und Ṯāʾ."],
    ar: ["ما مخرج الضاد؟", ["إحدى حافتي اللسان أو كلتاهما مع ما يحاذيها من الأضراس العليا", "طرف اللسان مع أطراف الثنايا العليا", "وسط اللسان مع ما يحاذيه من الحنك الأعلى", "أقصى اللسان مع ما يحاذيه من الحنك اللحمي"], "قال ابن الجزري: والضاد من حافته إذ وَلِيا الأضراس من أيسر أو يمناها. أما طرف اللسان مع أطراف الثنايا العليا فمخرج الظاء والذال والثاء."] },

  { id: "tjm-014", s: "tajweed", g: 3, d: 4, t: ["makharij", "makharij-lisan", "dad"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on makhārij al-ḥurūf",
    en: ["How do the books of tajwīd commonly describe the sides from which ḍād is produced?", ["From the left side it is easier and more common, from the right harder, from both sides hardest", "Only from the right side; the left side produces a different letter", "From both sides together is obligatory; one side alone is a fault", "From the left side only in waqf and from the right side in waṣl"], "Ḍād may be produced from either edge or from both. The commonly stated description is that the left side is easier and more usual, the right side harder and both sides together the hardest; all three are valid."],
    de: ["Wie beschreiben die Tajwīd-Bücher üblicherweise die Seiten, von denen Ḍād gebildet wird?", ["Links ist es leichter und häufiger, rechts schwerer, auf beiden Seiten am schwersten", "Nur rechts; die linke Seite ergibt einen anderen Buchstaben", "Beide Seiten zugleich sind Pflicht; eine Seite allein ist ein Fehler", "Links nur beim Anhalten, rechts beim Weiterlesen"], "Ḍād kann von einem der beiden Ränder oder von beiden gebildet werden. Üblicherweise heißt es: links leichter und häufiger, rechts schwerer, beidseitig am schwersten; alle drei Arten sind gültig."],
    ar: ["كيف تصف كتب التجويد عادةً الجهة التي تخرج منها الضاد؟", ["من الجهة اليسرى أيسر وأكثر، ومن اليمنى أعسر، ومن الجهتين معًا أعسر منهما", "من اليمنى فقط، وأما اليسرى فيخرج منها حرف آخر", "من الجهتين معًا وجوبًا، ومن جهة واحدة لحن", "من اليسرى عند الوقف ومن اليمنى عند الوصل"], "تخرج الضاد من إحدى الحافتين أو منهما، والمشهور أن خروجها من اليسرى أيسر وأكثر استعمالًا، ومن اليمنى أصعب، ومنهما معًا أصعب الوجوه، وكلها صحيحة."] },

  { id: "tjm-015", s: "tajweed", g: 2, d: 3, t: ["makharij", "makharij-lisan"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["Which letter is produced from the front part of the tongue's edges against the gums above the front teeth, below the makhraj of ḍād?", ["Lām", "Nūn", "Rāʾ", "Dāl"], "Lām comes from the edge of the tongue at its front end, running to its tip, against the gums of the upper front teeth. Nūn and rāʾ come from the tip of the tongue just next to it."],
    de: ["Welcher Buchstabe entsteht am vorderen Teil der Zungenränder an dem Zahnfleisch über den vorderen Zähnen, unterhalb der Stelle des Ḍād?", ["Lām", "Nūn", "Rāʾ", "Dāl"], "Lām kommt vom vorderen Zungenrand bis zur Spitze am Zahnfleisch der oberen Vorderzähne. Nūn und Rāʾ kommen unmittelbar daneben von der Zungenspitze."],
    ar: ["أيُّ حرف يخرج من أدنى حافتي اللسان إلى منتهى طرفه مع ما يحاذيه من لثة الأسنان العليا؟", ["اللام", "النون", "الراء", "الدال"], "اللام من أدنى حافة اللسان إلى منتهاها مع لثة الأسنان العليا، والنون والراء من طرف اللسان قريبًا منها."] },

  { id: "tjm-016", s: "tajweed", g: 3, d: 4, t: ["makharij", "makharij-lisan"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["How does the makhraj of rāʾ relate to that of nūn?", ["Close to it, but rāʾ involves more of the upper surface of the tongue tip", "Identical to it; they differ only by the ghunna", "Rāʾ is produced at the lips, nūn at the tip of the tongue", "Rāʾ comes from the middle of the tongue, far behind nūn"], "Ibn al-Jazarī: nūn comes from the tip of the tongue below the place of lām, and rāʾ is near nūn but enters more toward the back (upper surface) of the tongue. Al-Farrāʾ, by contrast, gave the three letters one makhraj."],
    de: ["Wie verhält sich die Artikulationsstelle des Rāʾ zu der des Nūn?", ["Nahe daran, doch beim Rāʾ ist mehr von der Oberseite der Zungenspitze beteiligt", "Identisch; sie unterscheiden sich nur durch die Ghunna", "Rāʾ entsteht an den Lippen, Nūn an der Zungenspitze", "Rāʾ kommt aus der Zungenmitte, weit hinter dem Nūn"], "Ibn al-Ǧazarī: Nūn kommt von der Zungenspitze unterhalb der Stelle des Lām, und Rāʾ liegt nahe am Nūn, geht aber mehr zur Oberseite der Zunge. Al-Farrāʾ dagegen gab allen drei Buchstaben eine Stelle."],
    ar: ["ما صلة مخرج الراء بمخرج النون؟", ["قريب منه، غير أن الراء أدخلُ إلى ظهر اللسان", "هو هو بعينه، ولا يفترقان إلا بالغنة", "الراء من الشفتين والنون من طرف اللسان", "الراء من وسط اللسان بعيدًا خلف النون"], "قال ابن الجزري: والنون من طرفه تحتُ اجعلوا، والرا يدانيه لظهرٍ أدخلُ؛ فالراء قريبة من مخرج النون لكنها أدخل إلى ظهر اللسان."] },

  { id: "tjm-017", s: "tajweed", g: 2, d: 2, t: ["makharij", "makharij-lisan"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["Which letters come from the tip of the tongue against the roots (gums) of the upper central incisors?", ["Ṭāʾ, dāl and tāʾ", "Ẓāʾ, dhāl and thāʾ", "Ṣād, zāy and sīn", "Jīm, shīn and yāʾ"], "The tip of the tongue with the roots of the upper incisors produces ṭāʾ, dāl and tāʾ. With the tips of the incisors it produces ẓāʾ, dhāl and thāʾ."],
    de: ["Welche Buchstaben entstehen mit der Zungenspitze an den Wurzeln (dem Zahnfleisch) der oberen mittleren Schneidezähne?", ["Ṭāʾ, Dāl und Tāʾ", "Ẓāʾ, Ḏāl und Ṯāʾ", "Ṣād, Zāy und Sīn", "Ǧīm, Šīn und Yāʾ"], "Die Zungenspitze an den Wurzeln der oberen Schneidezähne bildet Ṭāʾ, Dāl und Tāʾ. An den Spitzen der Schneidezähne bildet sie Ẓāʾ, Ḏāl und Ṯāʾ."],
    ar: ["ما الحروف التي تخرج من طرف اللسان مع أصول الثنايا العليا؟", ["الطاء والدال والتاء", "الظاء والذال والثاء", "الصاد والزاي والسين", "الجيم والشين والياء"], "يخرج من طرف اللسان مع أصول الثنايا العليا الطاء والدال والتاء، ومع أطرافها الظاء والذال والثاء."] },

  { id: "tjm-018", s: "tajweed", g: 2, d: 3, t: ["makharij", "makharij-lisan", "safir"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["Where are ṣād, zāy and sīn produced?", ["At the tip of the tongue just above the lower incisors, with a slight gap", "At the tip of the tongue against the roots of the upper incisors", "Between the inner lower lip and the tips of the upper incisors", "At the middle of the tongue against the hard palate"], "Ibn al-Jazarī says the whistling letters come from the tip of the tongue just above the lower incisors. A slight gap remains between tongue and teeth, through which the whistle (ṣafīr) passes."],
    de: ["Wo werden Ṣād, Zāy und Sīn gebildet?", ["An der Zungenspitze knapp über den unteren Schneidezähnen, mit einem kleinen Spalt", "An der Zungenspitze an den Wurzeln der oberen Schneidezähne", "Zwischen der Innenseite der Unterlippe und den oberen Schneidezähnen", "In der Zungenmitte am harten Gaumen"], "Nach Ibn al-Ǧazarī kommen die Pfeifbuchstaben von der Zungenspitze knapp über den unteren Schneidezähnen. Zwischen Zunge und Zähnen bleibt ein kleiner Spalt, durch den das Pfeifen (Ṣafīr) entweicht."],
    ar: ["من أين تخرج الصاد والزاي والسين؟", ["من طرف اللسان فويق الثنايا السفلى مع فرجة يسيرة", "من طرف اللسان مع أصول الثنايا العليا", "من باطن الشفة السفلى مع أطراف الثنايا العليا", "من وسط اللسان مع ما يحاذيه من الحنك الأعلى"], "قال ابن الجزري: والصفير مستكن منه ومن فوق الثنايا السفلى؛ فتخرج من طرف اللسان فويق الثنايا السفلى مع بقاء فرجة يسيرة يخرج منها الصفير."] },

  { id: "tjm-019", s: "tajweed", g: 2, d: 2, t: ["makharij", "makharij-lisan"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["Which letters are produced with the tip of the tongue against the tips (edges) of the upper incisors?", ["Ẓāʾ, dhāl and thāʾ", "Ṭāʾ, dāl and tāʾ", "Ṣād, zāy and sīn", "Fāʾ, wāw and bāʾ"], "Ẓāʾ, dhāl and thāʾ come from the tip of the tongue with the edges of the upper incisors, so the tongue tip appears slightly. Ṭāʾ, dāl and tāʾ are made further back, at the roots of the incisors."],
    de: ["Welche Buchstaben werden mit der Zungenspitze an den Spitzen (Kanten) der oberen Schneidezähne gebildet?", ["Ẓāʾ, Ḏāl und Ṯāʾ", "Ṭāʾ, Dāl und Tāʾ", "Ṣād, Zāy und Sīn", "Fāʾ, Wāw und Bāʾ"], "Ẓāʾ, Ḏāl und Ṯāʾ kommen von der Zungenspitze an den Kanten der oberen Schneidezähne, die Zungenspitze tritt dabei leicht hervor. Ṭāʾ, Dāl und Tāʾ liegen weiter hinten an den Zahnwurzeln."],
    ar: ["ما الحروف التي تخرج من طرف اللسان مع أطراف الثنايا العليا؟", ["الظاء والذال والثاء", "الطاء والدال والتاء", "الصاد والزاي والسين", "الفاء والواو والباء"], "تخرج الظاء والذال والثاء من طرف اللسان مع أطراف الثنايا العليا، أما الطاء والدال والتاء فمن أصول الثنايا."] },

  { id: "tjm-020", s: "tajweed", g: 1, d: 2, t: ["makharij", "makharij-shafatan"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["Which letter comes from the inner part of the lower lip against the tips of the upper incisors?", ["Fāʾ", "Bāʾ", "Mīm", "Thāʾ"], "Fāʾ is the only letter made between the lower lip and the upper incisors. Bāʾ and mīm need both lips, and thāʾ is made with the tongue tip."],
    de: ["Welcher Buchstabe entsteht zwischen der Innenseite der Unterlippe und den Spitzen der oberen Schneidezähne?", ["Fāʾ", "Bāʾ", "Mīm", "Ṯāʾ"], "Fāʾ ist der einzige Buchstabe zwischen Unterlippe und oberen Schneidezähnen. Bāʾ und Mīm brauchen beide Lippen, Ṯāʾ wird mit der Zungenspitze gebildet."],
    ar: ["أيُّ حرف يخرج من باطن الشفة السفلى مع أطراف الثنايا العليا؟", ["الفاء", "الباء", "الميم", "الثاء"], "الفاء وحدها تخرج من باطن الشفة السفلى مع أطراف الثنايا العليا، أما الباء والميم فمن الشفتين، والثاء من طرف اللسان."] },

  { id: "tjm-021", s: "tajweed", g: 1, d: 1, t: ["makharij", "makharij-shafatan"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["Which letters are produced with both lips?", ["Bāʾ, mīm and non-madd wāw", "Fāʾ, bāʾ and mīm", "Mīm, nūn and wāw", "Bāʾ, mīm and alif"], "Both lips produce bāʾ, mīm and the wāw that is not a madd letter. Fāʾ uses only the lower lip with the upper incisors."],
    de: ["Welche Buchstaben werden mit beiden Lippen gebildet?", ["Bāʾ, Mīm und Wāw, wenn es kein Dehnungsbuchstabe ist", "Fāʾ, Bāʾ und Mīm", "Mīm, Nūn und Wāw", "Bāʾ, Mīm und Alif"], "Beide Lippen bilden Bāʾ, Mīm und das Wāw, das kein Dehnungsbuchstabe ist. Fāʾ nutzt nur die Unterlippe mit den oberen Schneidezähnen."],
    ar: ["ما الحروف التي تخرج من الشفتين معًا؟", ["الباء والميم والواو غير المدية", "الفاء والباء والميم", "الميم والنون والواو", "الباء والميم والألف"], "يخرج من الشفتين معًا الباء والميم والواو غير المدية، أما الفاء فمن باطن الشفة السفلى مع أطراف الثنايا العليا."] },

  { id: "tjm-022", s: "tajweed", g: 2, d: 3, t: ["makharij", "makharij-shafatan"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on makhārij al-ḥurūf",
    en: ["How does the lip position of wāw differ from that of bāʾ and mīm?", ["For wāw the lips are rounded without closing; for bāʾ and mīm they close", "For wāw the lips close firmly; for bāʾ and mīm they only round", "For wāw only the lower lip moves; for bāʾ and mīm only the upper lip", "There is no difference; only the attributes distinguish them"], "Wāw is produced by rounding the lips with an opening in the middle, while bāʾ and mīm require the lips to close. That is why they share an area but are not one point."],
    de: ["Wie unterscheidet sich die Lippenstellung beim Wāw von der bei Bāʾ und Mīm?", ["Beim Wāw runden sich die Lippen ohne sich zu schließen, bei Bāʾ und Mīm schließen sie sich", "Beim Wāw schließen sich die Lippen fest, bei Bāʾ und Mīm runden sie sich nur", "Beim Wāw bewegt sich nur die Unterlippe, bei Bāʾ und Mīm nur die Oberlippe", "Es gibt keinen Unterschied; nur die Eigenschaften trennen sie"], "Wāw entsteht durch Runden der Lippen mit einer Öffnung in der Mitte, Bāʾ und Mīm erfordern den Lippenschluss. Daher teilen sie einen Bereich, bilden aber nicht denselben Punkt."],
    ar: ["كيف يختلف وضع الشفتين في الواو عنه في الباء والميم؟", ["في الواو تنضم الشفتان دون إطباق، وفي الباء والميم تنطبقان", "في الواو تنطبق الشفتان بقوة، وفي الباء والميم تنضمان فقط", "في الواو تتحرك السفلى وحدها، وفي الباء والميم العليا وحدها", "لا فرق بينها، وإنما تفترق بالصفات وحدها"], "تخرج الواو بانضمام الشفتين مع انفتاح يسير بينهما، والباء والميم بانطباقهما، فهي من موضع واحد لا من نقطة واحدة."] },

  { id: "tjm-023", s: "tajweed", g: 1, d: 2, t: ["makharij", "khayshum"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on makhārij al-ḥurūf",
    en: ["What is produced from the khayshūm (the nasal cavity)?", ["The ghunna", "The madd letters", "The whistle of ṣād and sīn", "The echo of the qalqala letters"], "Ibn al-Jazarī ends the makhārij with the ghunna, whose makhraj is the khayshūm. The madd letters belong to the jawf."],
    de: ["Was entsteht im Ḫayšūm (der Nasenhöhle)?", ["Die Ghunna (der Nasalklang)", "Die Dehnungsbuchstaben", "Das Pfeifen von Ṣād und Sīn", "Der Nachhall der Qalqala-Buchstaben"], "Ibn al-Ǧazarī schließt die Maḫāriǧ mit der Ghunna ab, deren Stelle der Ḫayšūm ist. Die Dehnungsbuchstaben gehören zum Ǧauf."],
    ar: ["ما الذي يخرج من الخيشوم؟", ["الغنة", "حروف المد", "صفير الصاد والسين", "صوت القلقلة"], "ختم ابن الجزري المخارج بقوله: وغنةٌ مخرجها الخيشوم، أما حروف المد فمن الجوف."] },

  { id: "tjm-024", s: "tajweed", g: 3, d: 3, t: ["makharij", "makharij-names"], src: "al-Khalīl ibn Aḥmad, Kitāb al-ʿAyn, introduction; Ibn al-Jazarī, al-Nashr, ch. on makhārij",
    en: ["Which letters are called niṭʿiyya, after the ridge at the front of the palate?", ["Ṭāʾ, dāl and tāʾ", "Ẓāʾ, dhāl and thāʾ", "Ṣād, zāy and sīn", "Lām, nūn and rāʾ"], "Niṭʿ is the hard ridge of the front palate, near which ṭāʾ, dāl and tāʾ are produced. Ẓāʾ, dhāl and thāʾ are lithawiyya and ṣād, zāy and sīn asaliyya."],
    de: ["Welche Buchstaben heißen niṭʿiyya, nach dem Wulst am vorderen Gaumen?", ["Ṭāʾ, Dāl und Tāʾ", "Ẓāʾ, Ḏāl und Ṯāʾ", "Ṣād, Zāy und Sīn", "Lām, Nūn und Rāʾ"], "Niṭʿ ist der harte Wulst am vorderen Gaumen, in dessen Nähe Ṭāʾ, Dāl und Tāʾ entstehen. Ẓāʾ, Ḏāl und Ṯāʾ heißen liṯawiyya, Ṣād, Zāy und Sīn asaliyya."],
    ar: ["ما الحروف التي تُسمّى النِّطْعية نسبةً إلى نطع الغار الأعلى؟", ["الطاء والدال والتاء", "الظاء والذال والثاء", "الصاد والزاي والسين", "اللام والنون والراء"], "النطع جلدة غار الحنك الأعلى، ومنه قرب مخرج الطاء والدال والتاء، أما الظاء والذال والثاء فلثوية، والصاد والزاي والسين أسلية."] },

  { id: "tjm-025", s: "tajweed", g: 3, d: 4, t: ["makharij", "makharij-names"], src: "al-Khalīl ibn Aḥmad, Kitāb al-ʿAyn, introduction; Ibn al-Jazarī, al-Nashr, ch. on makhārij",
    en: ["In al-Khalīl's naming of the letter groups, which letters are called shajariyya?", ["Jīm, shīn and yāʾ", "Qāf and kāf", "Ṣād, zāy and sīn", "Fāʾ, bāʾ and mīm"], "Shajr is the opening of the mouth between the jaws, where jīm, shīn and yāʾ are produced from the middle of the tongue. Qāf and kāf are lahawiyya, ṣād, zāy and sīn asaliyya, and the lip letters shafawiyya."],
    de: ["Welche Buchstaben heißen in al-Ḫalīls Benennung der Buchstabengruppen šaǧariyya?", ["Ǧīm, Šīn und Yāʾ", "Qāf und Kāf", "Ṣād, Zāy und Sīn", "Fāʾ, Bāʾ und Mīm"], "Šaǧr ist die Mundöffnung zwischen den Kiefern, wo Ǧīm, Šīn und Yāʾ aus der Zungenmitte entstehen. Qāf und Kāf heißen lahawiyya, Ṣād, Zāy und Sīn asaliyya, die Lippenbuchstaben šafawiyya."],
    ar: ["ما الحروف التي تُسمّى الشَّجْرية في تسمية الخليل لمجموعات الحروف؟", ["الجيم والشين والياء", "القاف والكاف", "الصاد والزاي والسين", "الفاء والباء والميم"], "الشجر مَفرج الفم، ومنه تخرج الجيم والشين والياء من وسط اللسان، أما القاف والكاف فلهويتان، والصاد والزاي والسين أسلية، وحروف الشفتين شفوية."] },

  { id: "tjm-026", s: "tajweed", g: 4, d: 4, t: ["makharij", "makharij-names"], src: "al-Khalīl ibn Aḥmad, Kitāb al-ʿAyn, introduction",
    en: ["Which two letters are called lahawiyya, after the uvula (lahāt)?", ["Qāf and kāf", "Ghayn and khāʾ", "Hamza and hāʾ", "Jīm and shīn"], "Qāf and kāf are produced at the back of the tongue near the uvula and are therefore called lahawiyya. Ghayn and khāʾ, though close, are throat letters."],
    de: ["Welche zwei Buchstaben heißen lahawiyya, nach dem Zäpfchen (Lahāt)?", ["Qāf und Kāf", "Ġain und Ḫāʾ", "Hamza und Hāʾ", "Ǧīm und Šīn"], "Qāf und Kāf entstehen am hinteren Zungenteil nahe dem Zäpfchen und heißen daher lahawiyya. Ġain und Ḫāʾ liegen zwar nahe, sind aber Kehlbuchstaben."],
    ar: ["ما الحرفان اللذان يُسمّيان اللَّهَويين نسبةً إلى اللهاة؟", ["القاف والكاف", "الغين والخاء", "الهمزة والهاء", "الجيم والشين"], "القاف والكاف تخرجان من أقصى اللسان قرب اللهاة فسُمّيتا لهويتين، أما الغين والخاء فحلقيتان وإن قرب مخرجهما."] },

  { id: "tjm-027", s: "tajweed", g: 4, d: 5, t: ["makharij", "makharij-names"], src: "al-Khalīl ibn Aḥmad, Kitāb al-ʿAyn, introduction",
    en: ["The names ḥalqiyya, lahawiyya, shajariyya, asaliyya, niṭʿiyya, lithawiyya, dhalqiyya and shafawiyya for the letter groups go back to whom?", ["al-Khalīl ibn Aḥmad al-Farāhīdī", "Abū ʿAmr al-Dānī", "Ibn al-Jazarī", "Makkī ibn Abī Ṭālib"], "These group names are from al-Khalīl in the introduction to Kitāb al-ʿAyn, where he ordered the letters by makhraj. Later tajwīd authors such as Ibn al-Jazarī took them over."],
    de: ["Auf wen gehen die Gruppennamen ḥalqiyya, lahawiyya, šaǧariyya, asaliyya, niṭʿiyya, liṯawiyya, ḏalqiyya und šafawiyya zurück?", ["Auf al-Ḫalīl ibn Aḥmad al-Farāhīdī", "Auf Abū ʿAmr ad-Dānī", "Auf Ibn al-Ǧazarī", "Auf Makkī ibn Abī Ṭālib"], "Diese Namen stammen von al-Ḫalīl aus der Einleitung zum Kitāb al-ʿAin, in dem er die Buchstaben nach ihrer Stelle ordnete. Spätere Tajwīd-Autoren wie Ibn al-Ǧazarī übernahmen sie."],
    ar: ["إلى مَن تعود تسمية مجموعات الحروف بالحلقية واللهوية والشجرية والأسلية والنطعية واللثوية والذلقية والشفوية؟", ["الخليل بن أحمد الفراهيدي", "أبو عمرو الداني", "ابن الجزري", "مكي بن أبي طالب"], "هذه الألقاب للخليل في مقدمة كتاب العين، إذ رتب الحروف على مخارجها، وتبعه فيها علماء التجويد كابن الجزري."] },

  { id: "tjm-028", s: "tajweed", g: 1, d: 2, t: ["makharij", "sifat"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Ṭāʾ and tāʾ share the same makhraj. What distinguishes them?", ["Their attributes (ṣifāt)", "Their point of articulation", "The length of their vowel", "The ghunna that one of them carries"], "Letters that share a makhraj are told apart by their ṣifāt. Ṭāʾ has jahr, istiʿlāʾ, iṭbāq and qalqala, while tāʾ has hams, istifāl and infitāḥ."],
    de: ["Ṭāʾ und Tāʾ haben dieselbe Artikulationsstelle. Was unterscheidet sie?", ["Ihre Eigenschaften (Ṣifāt)", "Ihre Artikulationsstelle", "Die Länge ihres Vokals", "Die Ghunna, die einer von ihnen trägt"], "Buchstaben mit gleicher Stelle unterscheiden sich durch ihre Ṣifāt. Ṭāʾ hat Ǧahr, Istiʿlāʾ, Iṭbāq und Qalqala, Tāʾ dagegen Hams, Istifāl und Infitāḥ."],
    ar: ["الطاء والتاء من مخرج واحد، فبمَ يتميزان؟", ["بصفاتهما", "بمخرجهما", "بطول حركتهما", "بغنةٍ في أحدهما"], "الحروف المتحدة مخرجًا تتمايز بالصفات؛ فالطاء مجهورة مستعلية مطبقة مقلقلة، والتاء مهموسة مستفلة منفتحة."] },

  // ---------- Ṣifāt al-ḥurūf ----------
  { id: "tjm-029", s: "tajweed", g: 1, d: 1, t: ["sifat", "definitions"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["What is meant by the ṣifa (attribute) of a letter in tajwīd?", ["The manner in which the letter is produced when it reaches its makhraj", "The place in the mouth or throat where the letter is produced", "The vowel sign written above or below the letter", "The rule that applies when the letter meets another letter"], "The makhraj tells where a letter is produced, the ṣifa how it is produced: with or without breath, sound flow, raising of the tongue and so on. Rules between letters (such as idghām) are a separate topic."],
    de: ["Was versteht man im Tajwīd unter der Ṣifa (Eigenschaft) eines Buchstabens?", ["Die Art, wie der Buchstabe an seiner Artikulationsstelle gebildet wird", "Die Stelle in Mund oder Kehle, an der der Buchstabe entsteht", "Das Vokalzeichen über oder unter dem Buchstaben", "Die Regel, die gilt, wenn er auf einen anderen Buchstaben trifft"], "Der Maḫraǧ sagt, wo ein Buchstabe entsteht, die Ṣifa, wie er entsteht: mit oder ohne Atem, mit fließendem oder gesperrtem Laut, mit gehobener Zunge usw. Regeln zwischen Buchstaben wie Idġām sind ein eigenes Thema."],
    ar: ["ما المقصود بصفة الحرف في علم التجويد؟", ["الكيفية العارضة للحرف عند حصوله في مخرجه", "الموضع الذي يخرج منه الحرف من الفم أو الحلق", "علامة الحركة المكتوبة فوق الحرف أو تحته", "الحكم الذي يعرض للحرف إذا لقي حرفًا آخر"], "المخرج يبيّن موضع خروج الحرف، والصفة تبيّن كيفيته من جريان النفس أو حبسه، وجريان الصوت أو انحباسه، وارتفاع اللسان ونحو ذلك. أما أحكام التقاء الحروف كالإدغام فباب آخر."] },

  { id: "tjm-030", s: "tajweed", g: 1, d: 2, t: ["sifat", "hams-jahr"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["What is hams?", ["The flow of breath when the letter is pronounced", "The trapping of the sound so that it cannot flow", "The raising of the back of the tongue to the palate", "A whistling sound that accompanies the letter"], "Hams is the audible flow of breath with the letter, because its reliance on the makhraj is weak. Its opposite, jahr, is the holding back of the breath."],
    de: ["Was ist Hams?", ["Das Ausströmen des Atems beim Sprechen des Buchstabens", "Das Einsperren des Lautes, sodass er nicht fließen kann", "Das Anheben des hinteren Zungenteils zum Gaumen", "Ein Pfeifton, der den Buchstaben begleitet"], "Hams ist das hörbare Ausströmen des Atems mit dem Buchstaben, weil er schwach auf seiner Stelle aufliegt. Das Gegenteil, Ǧahr, ist das Zurückhalten des Atems."],
    ar: ["ما الهمس؟", ["جريان النفس عند النطق بالحرف", "انحباس الصوت فلا يجري", "ارتفاع أقصى اللسان إلى الحنك الأعلى", "صوت زائد يشبه صوت الطائر"], "الهمس جريان النفس عند النطق بالحرف لضعف الاعتماد على المخرج، وضده الجهر وهو انحباس جريان النفس."] },

  { id: "tjm-031", s: "tajweed", g: 2, d: 2, t: ["sifat", "hams-jahr"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which mnemonic phrase gathers the ten letters of hams?", ["fa-ḥaththahu shakhṣun sakat", "ajid qaṭin bakat", "khuṣṣa ḍaghṭin qiẓ", "quṭbu jad"], "The hams letters are fāʾ, ḥāʾ, thāʾ, hāʾ, shīn, khāʾ, ṣād, sīn, kāf and tāʾ. The other phrases gather the letters of shidda, istiʿlāʾ and qalqala."],
    de: ["Welcher Merksatz fasst die zehn Hams-Buchstaben zusammen?", ["fa-ḥaṯṯahu šaḫṣun sakat", "aǧid qaṭin bakat", "ḫuṣṣa ḍaġṭin qiẓ", "quṭbu ǧad"], "Die Hams-Buchstaben sind Fāʾ, Ḥāʾ, Ṯāʾ, Hāʾ, Šīn, Ḫāʾ, Ṣād, Sīn, Kāf und Tāʾ. Die anderen Sätze fassen die Buchstaben von Šidda, Istiʿlāʾ und Qalqala zusammen."],
    ar: ["ما العبارة التي جمعت حروف الهمس العشرة؟", ["فحثه شخص سكت", "أجد قط بكت", "خص ضغط قظ", "قطب جد"], "حروف الهمس: الفاء والحاء والثاء والهاء والشين والخاء والصاد والسين والكاف والتاء، أما العبارات الأخرى فلحروف الشدة والاستعلاء والقلقلة."] },

  { id: "tjm-032", s: "tajweed", g: 2, d: 2, t: ["sifat", "shidda-rakhawa"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which mnemonic phrase gathers the eight letters of shidda?", ["ajid qaṭin bakat", "lin ʿumar", "fa-ḥaththahu shakhṣun sakat", "farra min lubb"], "Shidda letters are hamza, jīm, dāl, qāf, ṭāʾ, bāʾ, kāf and tāʾ. 'Lin ʿumar' gathers the in-between letters (tawassuṭ) and 'farra min lubb' the letters of idhlāq."],
    de: ["Welcher Merksatz fasst die acht Šidda-Buchstaben zusammen?", ["aǧid qaṭin bakat", "lin ʿumar", "fa-ḥaṯṯahu šaḫṣun sakat", "farra min lubb"], "Die Šidda-Buchstaben sind Hamza, Ǧīm, Dāl, Qāf, Ṭāʾ, Bāʾ, Kāf und Tāʾ. „lin ʿumar“ fasst die Zwischenbuchstaben (Tawassuṭ) zusammen, „farra min lubb“ die Iḏlāq-Buchstaben."],
    ar: ["ما العبارة التي جمعت حروف الشدة الثمانية؟", ["أجد قط بكت", "لن عمر", "فحثه شخص سكت", "فر من لب"], "حروف الشدة: الهمزة والجيم والدال والقاف والطاء والباء والكاف والتاء، أما «لن عمر» فحروف التوسط، و«فر من لب» فحروف الإذلاق."] },

  { id: "tjm-033", s: "tajweed", g: 2, d: 3, t: ["sifat", "shidda-rakhawa"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which letters are in-between (tawassuṭ) shidda and rakhāwa?", ["Lām, nūn, ʿayn, mīm and rāʾ", "Hamza, jīm, dāl, qāf and ṭāʾ", "Ṣād, zāy and sīn", "Wāw, yāʾ and alif"], "The phrase 'lin ʿumar' gathers lām, nūn, ʿayn, mīm and rāʾ. With these letters the sound neither stops completely as in shidda nor flows freely as in rakhāwa."],
    de: ["Welche Buchstaben stehen zwischen Šidda und Raḫāwa (Tawassuṭ)?", ["Lām, Nūn, ʿAin, Mīm und Rāʾ", "Hamza, Ǧīm, Dāl, Qāf und Ṭāʾ", "Ṣād, Zāy und Sīn", "Wāw, Yāʾ und Alif"], "Der Merksatz „lin ʿumar“ umfasst Lām, Nūn, ʿAin, Mīm und Rāʾ. Bei ihnen bricht der Laut weder ganz ab wie bei Šidda, noch fließt er frei wie bei Raḫāwa."],
    ar: ["ما حروف التوسط (البينية) بين الشدة والرخاوة؟", ["اللام والنون والعين والميم والراء", "الهمزة والجيم والدال والقاف والطاء", "الصاد والزاي والسين", "الواو والياء والألف"], "يجمعها قولهم «لن عمر»، وفيها لا ينحبس الصوت كله كما في الشدة ولا يجري كله كما في الرخاوة."] },

  { id: "tjm-034", s: "tajweed", g: 2, d: 3, t: ["sifat", "shidda-rakhawa", "definitions"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["How is shidda defined, as opposed to hams?", ["The sound is trapped because the letter rests firmly on its makhraj", "The breath flows because the letter rests weakly on its makhraj", "The tongue rises to the palate and the sound becomes full", "The letter is pronounced with a light echo at the end"], "Shidda concerns the sound (ṣawt): it is held back. Hams concerns the breath (nafas): it flows. That is why kāf and tāʾ can be both shadīd and mahmūs."],
    de: ["Wie wird Šidda im Unterschied zu Hams definiert?", ["Der Laut wird eingesperrt, weil der Buchstabe fest auf seiner Stelle aufliegt", "Der Atem strömt, weil der Buchstabe schwach auf seiner Stelle aufliegt", "Die Zunge hebt sich zum Gaumen und der Laut wird voll", "Der Buchstabe wird mit leichtem Nachhall am Ende gesprochen"], "Šidda betrifft den Laut (Ṣaut): Er wird zurückgehalten. Hams betrifft den Atem (Nafas): Er strömt. Darum können Kāf und Tāʾ zugleich šadīd und mahmūs sein."],
    ar: ["ما تعريف الشدة؟", ["انحباس الصوت لكمال قوة الاعتماد على المخرج", "جريان النفس لضعف الاعتماد على المخرج", "ارتفاع اللسان إلى الحنك وامتلاء الصوت", "النطق بالحرف مع نبرة خفيفة في آخره"], "الشدة متعلقة بالصوت وهو انحباسه، والهمس متعلق بالنفس وهو جريانه؛ ولذلك اجتمعت الشدة والهمس في الكاف والتاء."] },

  { id: "tjm-035", s: "tajweed", g: 2, d: 2, t: ["sifat", "istila-istifal"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which mnemonic phrase gathers the seven letters of istiʿlāʾ?", ["khuṣṣa ḍaghṭin qiẓ", "ajid qaṭin bakat", "quṭbu jad", "lin ʿumar"], "Istiʿlāʾ letters are khāʾ, ṣād, ḍād, ghayn, ṭāʾ, qāf and ẓāʾ. With them the back of the tongue rises toward the palate, giving them a full (mufakhkham) sound."],
    de: ["Welcher Merksatz fasst die sieben Istiʿlāʾ-Buchstaben zusammen?", ["ḫuṣṣa ḍaġṭin qiẓ", "aǧid qaṭin bakat", "quṭbu ǧad", "lin ʿumar"], "Die Istiʿlāʾ-Buchstaben sind Ḫāʾ, Ṣād, Ḍād, Ġain, Ṭāʾ, Qāf und Ẓāʾ. Bei ihnen hebt sich der hintere Zungenteil zum Gaumen, was ihnen einen vollen (mufaḫḫam) Klang gibt."],
    ar: ["ما العبارة التي جمعت حروف الاستعلاء السبعة؟", ["خص ضغط قظ", "أجد قط بكت", "قطب جد", "لن عمر"], "حروف الاستعلاء: الخاء والصاد والضاد والغين والطاء والقاف والظاء، وفيها يرتفع أقصى اللسان إلى الحنك الأعلى فتُفخَّم."] },
  { id: "tjm-036", s: "tajweed", g: 1, d: 2, t: ["sifat", "itbaq"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which are the four letters of iṭbāq?", ["Ṣād, ḍād, ṭāʾ and ẓāʾ", "Khāʾ, ghayn, qāf and ṭāʾ", "Ṣād, zāy, sīn and shīn", "Qāf, ṭāʾ, bāʾ and jīm"], "Ibn al-Jazarī: ṣād, ḍād, ṭāʾ and ẓāʾ are muṭbaqa. Khāʾ, ghayn and qāf are mustaʿliya but not muṭbaqa."],
    de: ["Welches sind die vier Iṭbāq-Buchstaben?", ["Ṣād, Ḍād, Ṭāʾ und Ẓāʾ", "Ḫāʾ, Ġain, Qāf und Ṭāʾ", "Ṣād, Zāy, Sīn und Šīn", "Qāf, Ṭāʾ, Bāʾ und Ǧīm"], "Ibn al-Ǧazarī: Ṣād, Ḍād, Ṭāʾ und Ẓāʾ sind muṭbaqa. Ḫāʾ, Ġain und Qāf haben Istiʿlāʾ, aber kein Iṭbāq."],
    ar: ["ما حروف الإطباق الأربعة؟", ["الصاد والضاد والطاء والظاء", "الخاء والغين والقاف والطاء", "الصاد والزاي والسين والشين", "القاف والطاء والباء والجيم"], "قال ابن الجزري: وصادُ ضادٌ طاءُ ظاءٌ مطبقة. أما الخاء والغين والقاف فمستعلية غير مطبقة."] },

  { id: "tjm-037", s: "tajweed", g: 2, d: 3, t: ["sifat", "idhlaq"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which mnemonic phrase gathers the six letters of idhlāq?", ["farra min lubb", "lin ʿumar", "quṭbu jad", "khuṣṣa ḍaghṭin qiẓ"], "The idhlāq letters are fāʾ, rāʾ, mīm, nūn, lām and bāʾ. They come from the tip of the tongue or the lips and are light on the tongue; all others are muṣmata."],
    de: ["Welcher Merksatz fasst die sechs Iḏlāq-Buchstaben zusammen?", ["farra min lubb", "lin ʿumar", "quṭbu ǧad", "ḫuṣṣa ḍaġṭin qiẓ"], "Die Iḏlāq-Buchstaben sind Fāʾ, Rāʾ, Mīm, Nūn, Lām und Bāʾ. Sie kommen von der Zungenspitze oder den Lippen und sind leicht zu sprechen; alle übrigen sind muṣmata."],
    ar: ["ما العبارة التي جمعت حروف الإذلاق الستة؟", ["فر من لب", "لن عمر", "قطب جد", "خص ضغط قظ"], "حروف الإذلاق: الفاء والراء والميم والنون واللام والباء، تخرج من ذلق اللسان أو الشفتين وتخف على اللسان، وما عداها مصمتة."] },

  { id: "tjm-038", s: "tajweed", g: 1, d: 2, t: ["sifat", "safir"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which letters carry the attribute of ṣafīr (whistling)?", ["Ṣād, zāy and sīn", "Shīn, sīn and ṣād", "Thāʾ, dhāl and ẓāʾ", "Fāʾ, thāʾ and sīn"], "Ibn al-Jazarī: ṣafīruhā ṣādun wa zāyun sīnu. Shīn has tafashshī, not ṣafīr."],
    de: ["Welche Buchstaben haben die Eigenschaft Ṣafīr (Pfeifen)?", ["Ṣād, Zāy und Sīn", "Šīn, Sīn und Ṣād", "Ṯāʾ, Ḏāl und Ẓāʾ", "Fāʾ, Ṯāʾ und Sīn"], "Ibn al-Ǧazarī nennt als Pfeifbuchstaben Ṣād, Zāy und Sīn. Šīn hat Tafaššī, nicht Ṣafīr."],
    ar: ["ما الحروف المتصفة بالصفير؟", ["الصاد والزاي والسين", "الشين والسين والصاد", "الثاء والذال والظاء", "الفاء والثاء والسين"], "قال ابن الجزري: صفيرها صادٌ وزايٌ سينُ. أما الشين فصفتها التفشي لا الصفير."] },

  { id: "tjm-039", s: "tajweed", g: 1, d: 1, t: ["sifat", "tafashshi"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which letter is described with tafashshī (spreading of the air in the mouth)?", ["Shīn", "Sīn", "Ḍād", "Rāʾ"], "In the Muqaddima tafashshī is the attribute of shīn. Ḍād has istiṭāla, rāʾ takrīr and sīn ṣafīr."],
    de: ["Welcher Buchstabe hat die Eigenschaft Tafaššī (Ausbreitung der Luft im Mund)?", ["Šīn", "Sīn", "Ḍād", "Rāʾ"], "In der Muqaddima ist Tafaššī die Eigenschaft des Šīn. Ḍād hat Istiṭāla, Rāʾ Takrīr und Sīn Ṣafīr."],
    ar: ["أيُّ حرف يتصف بالتفشي؟", ["الشين", "السين", "الضاد", "الراء"], "التفشي في المقدمة صفة الشين، أما الضاد فلها الاستطالة، والراء التكرير، والسين الصفير."] },

  { id: "tjm-040", s: "tajweed", g: 1, d: 1, t: ["sifat", "istitala", "dad"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which letter has the attribute of istiṭāla (extension)?", ["Ḍād", "Ẓāʾ", "Shīn", "Ṭāʾ"], "Ibn al-Jazarī: wa ḍādan istaṭil. Istiṭāla belongs only to ḍād and is one of the features that separate it from ẓāʾ."],
    de: ["Welcher Buchstabe hat die Eigenschaft Istiṭāla (Ausdehnung)?", ["Ḍād", "Ẓāʾ", "Šīn", "Ṭāʾ"], "Ibn al-Ǧazarī ordnet die Istiṭāla dem Ḍād zu. Sie gehört nur zu ihm und ist eines der Merkmale, die es vom Ẓāʾ trennen."],
    ar: ["أيُّ حرف يتصف بالاستطالة؟", ["الضاد", "الظاء", "الشين", "الطاء"], "قال ابن الجزري: وضادًا استطل. والاستطالة خاصة بالضاد، وهي مما يميزها عن الظاء."] },

  { id: "tjm-041", s: "tajweed", g: 1, d: 2, t: ["sifat", "takrir"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which letter is described with takrīr (repetition)?", ["Rāʾ", "Lām", "Nūn", "Qāf"], "Takrīr is the readiness of the rāʾ to repeat because the tongue tip trembles. Lām shares inḥirāf with rāʾ, but not takrīr."],
    de: ["Welcher Buchstabe hat die Eigenschaft Takrīr (Wiederholung)?", ["Rāʾ", "Lām", "Nūn", "Qāf"], "Takrīr ist die Neigung des Rāʾ zur Wiederholung, weil die Zungenspitze vibriert. Lām teilt mit dem Rāʾ das Inḥirāf, nicht aber das Takrīr."],
    ar: ["أيُّ حرف يتصف بالتكرير؟", ["الراء", "اللام", "النون", "القاف"], "التكرير قبول الراء للتكرار لارتعاد طرف اللسان بها، واللام تشارك الراء في الانحراف لا في التكرير."] },

  { id: "tjm-042", s: "tajweed", g: 2, d: 2, t: ["sifat", "inhiraf"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which letters have the attribute of inḥirāf (deviation)?", ["Lām and rāʾ", "Wāw and yāʾ", "Nūn and mīm", "Ḍād and shīn"], "Ibn al-Jazarī: wa-l-inḥirāfu ṣuḥḥiḥā fī al-lāmi wa-l-rā. Their sound deviates from its makhraj toward another; wāw and yāʾ (after fatḥa) have līn."],
    de: ["Welche Buchstaben haben die Eigenschaft Inḥirāf (Abweichung)?", ["Lām und Rāʾ", "Wāw und Yāʾ", "Nūn und Mīm", "Ḍād und Šīn"], "Ibn al-Ǧazarī ordnet das Inḥirāf Lām und Rāʾ zu. Ihr Laut weicht von seiner Stelle zu einer anderen ab; Wāw und Yāʾ nach Fatḥa haben Līn."],
    ar: ["ما الحرفان المتصفان بالانحراف؟", ["اللام والراء", "الواو والياء", "النون والميم", "الضاد والشين"], "قال ابن الجزري: والانحراف صُحِّحا في اللام والرا. وفيهما ينحرف الصوت عن مخرجه إلى غيره، أما الواو والياء بعد الفتح فلهما اللين."] },

  { id: "tjm-043", s: "tajweed", g: 2, d: 3, t: ["sifat", "lin"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which letters carry the attribute of līn (softness)?", ["Wāw and yāʾ when sākin and preceded by a fatḥa", "Wāw and yāʾ when sākin and preceded by their matching vowel", "Alif, wāw and yāʾ in every position", "Lām and nūn when they are mushaddad"], "Līn is wāw sākina or yāʾ sākina after a fatḥa, pronounced easily without strain. After a matching vowel (ḍamma, kasra) they are madd letters, which is a different category."],
    de: ["Welche Buchstaben haben die Eigenschaft Līn (Weichheit)?", ["Wāw und Yāʾ, wenn sie sākin sind und ihnen eine Fatḥa vorausgeht", "Wāw und Yāʾ, wenn sie sākin sind und der passende Vokal vorausgeht", "Alif, Wāw und Yāʾ in jeder Stellung", "Lām und Nūn, wenn sie verdoppelt sind"], "Līn sind Wāw sākina und Yāʾ sākina nach einer Fatḥa, die mühelos gesprochen werden. Nach dem passenden Vokal (Ḍamma, Kasra) sind sie Dehnungsbuchstaben, eine andere Kategorie."],
    ar: ["ما الحرفان المتصفان باللين؟", ["الواو والياء الساكنتان المفتوح ما قبلهما", "الواو والياء الساكنتان بعد حركة مجانسة", "الألف والواو والياء في كل حال", "اللام والنون إذا شُدِّدتا"], "قال ابن الجزري: واوٌ وياءٌ سكنا وانفتحا قبلهما. فإن جانسهما ما قبلهما فهما حرفا مد."] },

  { id: "tjm-044", s: "tajweed", g: 1, d: 2, t: ["sifat", "qalqala-sifa"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which mnemonic phrase gathers the letters that carry the attribute of qalqala?", ["quṭbu jad", "ajid qaṭin bakat", "khuṣṣa ḍaghṭin qiẓ", "fa-ḥaththahu shakhṣun sakat"], "The qalqala letters are qāf, ṭāʾ, bāʾ, jīm and dāl. All five are both majhūr and shadīd, which is why the sound needs a slight release when they are sākin."],
    de: ["Welcher Merksatz fasst die Buchstaben mit der Eigenschaft Qalqala zusammen?", ["quṭbu ǧad", "aǧid qaṭin bakat", "ḫuṣṣa ḍaġṭin qiẓ", "fa-ḥaṯṯahu šaḫṣun sakat"], "Die Qalqala-Buchstaben sind Qāf, Ṭāʾ, Bāʾ, Ǧīm und Dāl. Alle fünf sind maǧhūr und šadīd, darum braucht ihr Laut im Sukūn eine leichte Lösung."],
    ar: ["ما العبارة التي جمعت حروف القلقلة؟", ["قطب جد", "أجد قط بكت", "خص ضغط قظ", "فحثه شخص سكت"], "حروف القلقلة: القاف والطاء والباء والجيم والدال، وكلها مجهورة شديدة، فاحتاجت عند سكونها إلى نبرة تُظهرها."] },

  { id: "tjm-045", s: "tajweed", g: 3, d: 3, t: ["sifat", "itbaq", "istila-istifal"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["Which statement about iṭbāq and istiʿlāʾ is correct?", ["Every muṭbaq letter is mustaʿlī, but not every mustaʿlī letter is muṭbaq", "Every mustaʿlī letter is muṭbaq, but not every muṭbaq letter is mustaʿlī", "They are two names for the same seven letters", "They have no letter in common"], "In istiʿlāʾ the back of the tongue rises; in iṭbāq the tongue also presses against the palate and encloses the sound. The four muṭbaq letters are all among the seven mustaʿliya; khāʾ, ghayn and qāf are mustaʿliya only."],
    de: ["Welche Aussage über Iṭbāq und Istiʿlāʾ ist richtig?", ["Jeder muṭbaq-Buchstabe ist mustaʿlī, aber nicht jeder mustaʿlī-Buchstabe ist muṭbaq", "Jeder mustaʿlī-Buchstabe ist muṭbaq, aber nicht jeder muṭbaq-Buchstabe ist mustaʿlī", "Es sind zwei Namen für dieselben sieben Buchstaben", "Sie haben keinen Buchstaben gemeinsam"], "Bei Istiʿlāʾ hebt sich der hintere Zungenteil; bei Iṭbāq legt sich die Zunge zudem an den Gaumen und schließt den Laut ein. Die vier muṭbaq-Buchstaben gehören alle zu den sieben mustaʿliya; Ḫāʾ, Ġain und Qāf haben nur Istiʿlāʾ."],
    ar: ["أيُّ العبارات الآتية صحيحة في العلاقة بين الإطباق والاستعلاء؟", ["كل مطبق مستعلٍ، وليس كل مستعلٍ مطبقًا", "كل مستعلٍ مطبق، وليس كل مطبق مستعليًا", "هما اسمان لحروف سبعة بعينها", "لا يشتركان في حرف واحد"], "في الاستعلاء يرتفع أقصى اللسان، وفي الإطباق ينطبق اللسان على الحنك وينحصر الصوت بينهما. فحروف الإطباق الأربعة داخلة في حروف الاستعلاء السبعة، والخاء والغين والقاف مستعلية فقط."] },

  { id: "tjm-046", s: "tajweed", g: 3, d: 4, t: ["sifat", "hams-jahr", "shidda-rakhawa"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["Which two letters combine hams with shidda?", ["Kāf and tāʾ", "Qāf and ṭāʾ", "Sīn and ṣād", "Hamza and hāʾ"], "Kāf and tāʾ appear in both mnemonics, 'fa-ḥaththahu shakhṣun sakat' and 'ajid qaṭin bakat'. Their sound is cut off, yet a little breath follows it; this breath should be audible but not exaggerated."],
    de: ["Welche zwei Buchstaben verbinden Hams mit Šidda?", ["Kāf und Tāʾ", "Qāf und Ṭāʾ", "Sīn und Ṣād", "Hamza und Hāʾ"], "Kāf und Tāʾ stehen in beiden Merksätzen, „fa-ḥaṯṯahu šaḫṣun sakat“ und „aǧid qaṭin bakat“. Ihr Laut bricht ab, doch ein wenig Atem folgt; dieser soll hörbar, aber nicht übertrieben sein."],
    ar: ["ما الحرفان اللذان اجتمع فيهما الهمس والشدة؟", ["الكاف والتاء", "القاف والطاء", "السين والصاد", "الهمزة والهاء"], "الكاف والتاء مذكورتان في «فحثه شخص سكت» و«أجد قط بكت»؛ فينحبس صوتهما ثم يجري بعده نفس يسير ينبغي إظهاره دون مبالغة."] },

  { id: "tjm-047", s: "tajweed", g: 3, d: 3, t: ["sifat", "takrir"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["What is the reciter's task regarding the takrīr of rāʾ, according to the Muqaddima?", ["To conceal it, especially when the rāʾ is mushaddad", "To make it clearly heard so that the rāʾ is recognised", "To apply it only when stopping on a rāʾ", "To repeat the rāʾ twice when it carries a shadda"], "Ibn al-Jazarī says: wa akhfi takrīran idhā tushaddadu. Takrīr is described so that it can be avoided; the tongue should not tremble repeatedly, above all on a doubled rāʾ."],
    de: ["Was ist nach der Muqaddima die Aufgabe des Rezitators beim Takrīr des Rāʾ?", ["Es zu verbergen, besonders wenn das Rāʾ verdoppelt ist", "Es deutlich hörbar zu machen, damit man das Rāʾ erkennt", "Es nur beim Anhalten auf einem Rāʾ anzuwenden", "Das Rāʾ bei einer Šadda zweimal zu wiederholen"], "Ibn al-Ǧazarī sagt sinngemäß: Verbirg das Takrīr, wenn das Rāʾ verdoppelt ist. Takrīr wird beschrieben, damit man es vermeidet; die Zunge soll nicht mehrfach vibrieren, vor allem nicht beim verdoppelten Rāʾ."],
    ar: ["ما المطلوب من القارئ في تكرير الراء بحسب المقدمة الجزرية؟", ["إخفاؤه ولا سيما إذا كانت الراء مشددة", "إظهاره ليُعرف به حرف الراء", "الإتيان به عند الوقف على الراء فقط", "تكرار الراء مرتين إذا شُدِّدت"], "قال ابن الجزري: وأخفِ تكريرًا إذا تُشدَّدُ. فالتكرير يُعرف ليُجتنب، فلا يرتعد اللسان بالراء مرات، خاصة في المشددة."] },

  { id: "tjm-048", s: "tajweed", g: 3, d: 4, t: ["sifat", "idhlaq"], src: "al-Khalīl ibn Aḥmad, Kitāb al-ʿAyn, introduction; Ibn Jinnī, Sirr Ṣināʿat al-Iʿrāb",
    en: ["What property of Arabic words is linked with the idhlāq letters?", ["Genuine Arabic roots of four or five letters almost always contain at least one of them", "No genuine Arabic word may begin with one of them", "They never appear twice in the same root", "They are dropped when a word is stopped on"], "Al-Khalīl observed that genuine quadriliteral and quinqueliteral roots contain at least one of the light letters fāʾ, rāʾ, mīm, nūn, lām or bāʾ. The others are called muṣmata ('silenced'), because they do not form such a root on their own."],
    de: ["Welche Eigenschaft arabischer Wörter hängt mit den Iḏlāq-Buchstaben zusammen?", ["Echte arabische Wurzeln aus vier oder fünf Buchstaben enthalten fast immer mindestens einen von ihnen", "Kein echtes arabisches Wort darf mit einem von ihnen beginnen", "Sie kommen nie zweimal in derselben Wurzel vor", "Sie fallen weg, wenn man auf einem Wort anhält"], "Al-Ḫalīl stellte fest, dass echte vier- und fünfradikalige Wurzeln mindestens einen der leichten Buchstaben Fāʾ, Rāʾ, Mīm, Nūn, Lām oder Bāʾ enthalten. Die übrigen heißen muṣmata („verstummt“), weil sie allein keine solche Wurzel bilden."],
    ar: ["ما الخاصية في كلام العرب المرتبطة بحروف الإذلاق؟", ["أن الكلمة العربية الأصيلة الرباعية أو الخماسية الأصول لا تكاد تخلو من حرف منها", "أن الكلمة العربية الأصيلة لا تبدأ بحرف منها", "أنها لا تتكرر في جذر واحد", "أنها تُحذف عند الوقف على الكلمة"], "لاحظ الخليل أن الرباعي والخماسي الأصيل لا يخلو من حرف من حروف الذلاقة، وسُمّيت البقية مصمتة لأنها مُنعت من أن ينفرد بها بناء رباعي أو خماسي."] },

  { id: "tjm-049", s: "tajweed", g: 3, d: 3, t: ["sifat", "safir", "definitions"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["How is ṣafīr defined?", ["An additional sharp sound resembling a whistle that accompanies the letter", "The spreading of air across the mouth when the letter is pronounced", "A slight trembling of the tongue tip during the letter", "A nasal sound that comes from the khayshūm"], "Ṣafīr is an extra sound like the whistle of a bird, produced as the air passes the narrow gap between tongue tip and incisors. Spreading of air is tafashshī, trembling is takrīr, the nasal sound is ghunna."],
    de: ["Wie wird Ṣafīr definiert?", ["Ein zusätzlicher scharfer, pfeifähnlicher Laut, der den Buchstaben begleitet", "Die Ausbreitung der Luft im Mund beim Sprechen des Buchstabens", "Ein leichtes Vibrieren der Zungenspitze beim Buchstaben", "Ein Nasalklang aus dem Ḫayšūm"], "Ṣafīr ist ein zusätzlicher Laut wie das Pfeifen eines Vogels, der entsteht, wenn die Luft den engen Spalt zwischen Zungenspitze und Schneidezähnen passiert. Ausbreitung der Luft ist Tafaššī, Vibrieren Takrīr, Nasalklang Ghunna."],
    ar: ["ما تعريف الصفير؟", ["صوت زائد حادّ يشبه صوت الطائر يصاحب الحرف", "انتشار الهواء في الفم عند النطق بالحرف", "ارتعاد طرف اللسان عند النطق بالحرف", "صوت أغن يخرج من الخيشوم"], "الصفير صوت زائد يشبه صفير الطائر، يحدث بمرور الهواء من الفرجة الضيقة بين طرف اللسان والثنايا. أما انتشار الهواء فالتفشي، والارتعاد التكرير، والصوت الأغن الغنة."] },

  { id: "tjm-050", s: "tajweed", g: 3, d: 4, t: ["sifat", "istitala", "dad"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["What is meant by the istiṭāla of ḍād?", ["The sound extends along the edge of the tongue from the start to the end of its makhraj", "The vowel after ḍād is lengthened by two counts", "The ḍād is held longer when it is stopped on", "The tongue rises to the palate and the ḍād becomes full"], "Istiṭāla is an extension of the sound within the makhraj itself, which is long, from the back of the tongue's edge toward the lām. It has nothing to do with madd or with lengthening the time of the letter; raising the tongue is istiʿlāʾ."],
    de: ["Was bedeutet die Istiṭāla des Ḍād?", ["Der Laut erstreckt sich entlang des Zungenrandes vom Anfang bis zum Ende seiner Stelle", "Der Vokal nach dem Ḍād wird um zwei Zählzeiten gedehnt", "Das Ḍād wird beim Anhalten länger gehalten", "Die Zunge hebt sich zum Gaumen und das Ḍād wird voll"], "Istiṭāla ist eine Ausdehnung des Lautes innerhalb der langen Artikulationsstelle selbst, vom hinteren Zungenrand bis zur Stelle des Lām. Sie hat nichts mit Madd oder einer zeitlichen Dehnung zu tun; das Heben der Zunge ist Istiʿlāʾ."],
    ar: ["ما المقصود باستطالة الضاد؟", ["امتداد الصوت على حافة اللسان من أول مخرجها إلى آخره", "مدّ الحركة التي بعد الضاد حركتين", "إطالة زمن الضاد عند الوقف عليها", "ارتفاع اللسان إلى الحنك وتفخيم الضاد"], "الاستطالة امتداد الصوت في مخرج الضاد نفسه، وهو مخرج مستطيل من أول حافة اللسان إلى ما يلي مخرج اللام، ولا علاقة لها بالمد الزمني، أما ارتفاع اللسان فهو الاستعلاء."] },

  { id: "tjm-051", s: "tajweed", g: 3, d: 3, t: ["sifat", "tafashshi", "definitions"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["How is tafashshī defined?", ["The spreading of the air in the mouth when the letter is pronounced", "The extension of the sound along the edge of the tongue", "The flow of breath because the letter rests weakly on its makhraj", "The deviation of the sound from its makhraj toward another"], "Tafashshī means the air spreads widely in the mouth, as with shīn. The extension along the tongue's edge is istiṭāla, flow of breath is hams and deviation is inḥirāf."],
    de: ["Wie wird Tafaššī definiert?", ["Die Ausbreitung der Luft im Mund beim Sprechen des Buchstabens", "Die Ausdehnung des Lautes entlang des Zungenrandes", "Das Strömen des Atems, weil der Buchstabe schwach aufliegt", "Die Abweichung des Lautes von seiner Stelle zu einer anderen"], "Tafaššī bedeutet, dass sich die Luft weit im Mund ausbreitet, wie beim Šīn. Die Ausdehnung entlang des Zungenrandes ist Istiṭāla, das Strömen des Atems Hams, die Abweichung Inḥirāf."],
    ar: ["ما تعريف التفشي؟", ["انتشار الهواء في الفم عند النطق بالحرف", "امتداد الصوت على حافة اللسان", "جريان النفس لضعف الاعتماد على المخرج", "ميل الصوت عن مخرجه إلى مخرج غيره"], "التفشي انتشار الهواء في الفم كما في الشين، أما امتداد الصوت على حافة اللسان فالاستطالة، وجريان النفس الهمس، وميل الصوت الانحراف."] },

  { id: "tjm-052", s: "tajweed", g: 4, d: 5, t: ["sifat", "itbaq"], src: "Sībawayh, al-Kitāb, ch. on idghām (makhārij and ṣifāt)",
    en: ["Sībawayh remarks that without iṭbāq certain letters would turn into others. Without iṭbāq, ṭāʾ would become which letter?", ["Dāl", "Tāʾ", "Ẓāʾ", "Ḍād"], "Sībawayh: without iṭbāq ṭāʾ would be dāl, ṣād sīn, ẓāʾ dhāl, and ḍād would leave the language. Ṭāʾ becomes dāl rather than tāʾ because ṭāʾ is majhūr like dāl, whereas tāʾ is mahmūs."],
    de: ["Sībawaih bemerkt, dass ohne Iṭbāq bestimmte Buchstaben zu anderen würden. Zu welchem Buchstaben würde Ṭāʾ ohne Iṭbāq?", ["Zu Dāl", "Zu Tāʾ", "Zu Ẓāʾ", "Zu Ḍād"], "Sībawaih: Ohne Iṭbāq wäre Ṭāʾ ein Dāl, Ṣād ein Sīn, Ẓāʾ ein Ḏāl, und Ḍād verschwände aus der Sprache. Ṭāʾ wird zu Dāl und nicht zu Tāʾ, weil Ṭāʾ wie Dāl maǧhūr ist, Tāʾ dagegen mahmūs."],
    ar: ["ذكر سيبويه أنه لولا الإطباق لصارت بعض الحروف حروفًا أخرى. فلولا الإطباق لصارت الطاء أيَّ حرف؟", ["دالًا", "تاءً", "ظاءً", "ضادًا"], "قال سيبويه: لولا الإطباق لصارت الطاء دالًا، والصاد سينًا، والظاء ذالًا، ولخرجت الضاد من الكلام. وصارت الطاء دالًا لا تاءً لأنها مجهورة كالدال، والتاء مهموسة."] },

  { id: "tjm-053", s: "tajweed", g: 4, d: 4, t: ["sifat", "takrir", "inhiraf"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on ṣifāt al-ḥurūf",
    en: ["Which letter is commonly cited as carrying seven attributes, the highest number of any letter?", ["Rāʾ", "Ṭāʾ", "Ḍād", "Ṣād"], "Rāʾ has jahr, tawassuṭ, istifāl, infitāḥ and idhlāq from the paired group, plus inḥirāf and takrīr. Ṭāʾ, ḍād and ṣād each have six."],
    de: ["Welcher Buchstabe wird üblicherweise mit sieben Eigenschaften genannt, der höchsten Zahl aller Buchstaben?", ["Rāʾ", "Ṭāʾ", "Ḍād", "Ṣād"], "Rāʾ hat aus der Gruppe der Gegensatzpaare Ǧahr, Tawassuṭ, Istifāl, Infitāḥ und Iḏlāq, dazu Inḥirāf und Takrīr. Ṭāʾ, Ḍād und Ṣād haben jeweils sechs."],
    ar: ["أيُّ حرف يُذكر عادةً أنه اجتمعت فيه سبع صفات، وهو أكثر الحروف صفاتٍ؟", ["الراء", "الطاء", "الضاد", "الصاد"], "للراء من الصفات المتضادة: الجهر والتوسط والاستفال والانفتاح والإذلاق، ومن غير المتضادة: الانحراف والتكرير، فهي سبع. وللطاء والضاد والصاد ست صفات."] },

  { id: "tjm-054", s: "tajweed", g: 3, d: 4, t: ["sifat", "sifat-opposites"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["How many attributes from the group of paired opposites does every letter carry?", ["Five, one from each pair", "Three, from the first three pairs", "Seven, with the in-between attribute", "Two, either strong or weak"], "There are five pairs: hams/jahr, shidda/rakhāwa (with tawassuṭ between them), istiʿlāʾ/istifāl, iṭbāq/infitāḥ and idhlāq/iṣmāt. Every letter takes exactly one side of each pair; the attributes without opposites are added to some letters only."],
    de: ["Wie viele Eigenschaften aus der Gruppe der Gegensatzpaare hat jeder Buchstabe?", ["Fünf, eine aus jedem Paar", "Drei, aus den ersten drei Paaren", "Sieben, samt der Zwischeneigenschaft", "Zwei, entweder starke oder schwache"], "Es gibt fünf Paare: Hams/Ǧahr, Šidda/Raḫāwa (mit Tawassuṭ dazwischen), Istiʿlāʾ/Istifāl, Iṭbāq/Infitāḥ und Iḏlāq/Iṣmāt. Jeder Buchstabe hat genau eine Seite jedes Paares; die Eigenschaften ohne Gegenteil kommen nur bei manchen Buchstaben hinzu."],
    ar: ["كم صفة من الصفات المتضادة تجتمع في كل حرف؟", ["خمس، واحدة من كل زوج", "ثلاث، من الأزواج الثلاثة الأولى", "سبع، مع صفة التوسط", "اثنتان، قوية أو ضعيفة"], "الأزواج خمسة: الهمس والجهر، والشدة والرخاوة وبينهما التوسط، والاستعلاء والاستفال، والإطباق والانفتاح، والإذلاق والإصمات. ولكل حرف صفة واحدة من كل زوج، أما الصفات التي لا ضد لها فتختص ببعض الحروف."] },

  { id: "tjm-055", s: "tajweed", g: 3, d: 3, t: ["sifat", "letter-strength"], src: "Makkī ibn Abī Ṭālib, al-Riʿāya li-Tajwīd al-Qirāʾa, section on the attributes of the letters",
    en: ["Which of the following attributes is classed among the weak ones?", ["Hams", "Jahr", "Iṭbāq", "Ṣafīr"], "Hams is weak because the breath escapes and the letter rests weakly on its makhraj. Jahr, iṭbāq and ṣafīr are counted among the strong attributes."],
    de: ["Welche der folgenden Eigenschaften gilt als schwach?", ["Hams", "Ǧahr", "Iṭbāq", "Ṣafīr"], "Hams ist schwach, weil der Atem entweicht und der Buchstabe nur schwach aufliegt. Ǧahr, Iṭbāq und Ṣafīr zählen zu den starken Eigenschaften."],
    ar: ["أيُّ الصفات الآتية من الصفات الضعيفة؟", ["الهمس", "الجهر", "الإطباق", "الصفير"], "الهمس صفة ضعيفة لجريان النفس وضعف الاعتماد على المخرج، أما الجهر والإطباق والصفير فمن الصفات القوية."] },

  { id: "tjm-056", s: "tajweed", g: 3, d: 3, t: ["sifat", "letter-strength"], src: "Makkī ibn Abī Ṭālib, al-Riʿāya li-Tajwīd al-Qirāʾa, section on the attributes of the letters",
    en: ["Which letter is commonly described as the strongest letter, and why?", ["Ṭāʾ, because it combines jahr, shidda, istiʿlāʾ, iṭbāq and qalqala", "Rāʾ, because it carries the most attributes of any letter", "Ḍād, because it is the only letter with istiṭāla", "Qāf, because it is the deepest letter of the tongue"], "Strength is judged by the quality of the attributes, not their number. Ṭāʾ gathers almost all strong attributes; rāʾ has more attributes in total, but several of them are not strong."],
    de: ["Welcher Buchstabe wird üblicherweise als stärkster Buchstabe bezeichnet, und warum?", ["Ṭāʾ, weil es Ǧahr, Šidda, Istiʿlāʾ, Iṭbāq und Qalqala vereint", "Rāʾ, weil es die meisten Eigenschaften aller Buchstaben hat", "Ḍād, weil es als einziges Istiṭāla besitzt", "Qāf, weil es der tiefste Zungenbuchstabe ist"], "Die Stärke richtet sich nach der Art der Eigenschaften, nicht nach ihrer Zahl. Ṭāʾ vereint fast alle starken Eigenschaften; Rāʾ hat insgesamt mehr Eigenschaften, doch mehrere davon sind nicht stark."],
    ar: ["أيُّ الحروف يُوصف عادةً بأنه أقوى الحروف، ولماذا؟", ["الطاء؛ لاجتماع الجهر والشدة والاستعلاء والإطباق والقلقلة فيها", "الراء؛ لأنها أكثر الحروف صفاتٍ", "الضاد؛ لأنها انفردت بالاستطالة", "القاف؛ لأنها أبعد حروف اللسان مخرجًا"], "العبرة في القوة بنوع الصفات لا بعددها؛ فالطاء جمعت أكثر الصفات القوية، والراء وإن كثرت صفاتها ففيها صفات غير قوية."] },

  { id: "tjm-057", s: "tajweed", g: 2, d: 3, t: ["sifat", "hams-jahr", "safir"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["Sīn and zāy share makhraj, ṣafīr, rakhāwa and istifāl. Which pair of attributes separates them?", ["Hams in sīn and jahr in zāy", "Istiʿlāʾ in sīn and istifāl in zāy", "Shidda in zāy and rakhāwa in sīn", "Iṭbāq in zāy and infitāḥ in sīn"], "Sīn is mahmūs, so breath flows with it, while zāy is majhūr. If a reciter lets the breath run with zāy, it drifts toward sīn."],
    de: ["Sīn und Zāy teilen Stelle, Ṣafīr, Raḫāwa und Istifāl. Welches Eigenschaftspaar trennt sie?", ["Hams beim Sīn und Ǧahr beim Zāy", "Istiʿlāʾ beim Sīn und Istifāl beim Zāy", "Šidda beim Zāy und Raḫāwa beim Sīn", "Iṭbāq beim Zāy und Infitāḥ beim Sīn"], "Sīn ist mahmūs, der Atem strömt mit; Zāy ist maǧhūr. Lässt man beim Zāy den Atem strömen, nähert es sich dem Sīn."],
    ar: ["تشترك السين والزاي في المخرج والصفير والرخاوة والاستفال، فما الصفة التي تفرق بينهما؟", ["الهمس في السين والجهر في الزاي", "الاستعلاء في السين والاستفال في الزاي", "الشدة في الزاي والرخاوة في السين", "الإطباق في الزاي والانفتاح في السين"], "السين مهموسة يجري معها النفس، والزاي مجهورة، فإذا أُجري النفس مع الزاي قربت من السين."] },

  { id: "tjm-058", s: "tajweed", g: 2, d: 3, t: ["sifat", "itbaq", "istila-istifal"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["Ṣād and sīn share makhraj, hams, rakhāwa and ṣafīr. What separates them?", ["Istiʿlāʾ and iṭbāq in ṣād, istifāl and infitāḥ in sīn", "Jahr in ṣād and hams in sīn", "Shidda in ṣād and rakhāwa in sīn", "Tafashshī in ṣād and ṣafīr in sīn"], "Ṣād is raised and enclosed, sīn is lowered and open. This is why a weak iṭbāq turns ṣād into sīn, as Sībawayh noted."],
    de: ["Ṣād und Sīn teilen Stelle, Hams, Raḫāwa und Ṣafīr. Was trennt sie?", ["Istiʿlāʾ und Iṭbāq beim Ṣād, Istifāl und Infitāḥ beim Sīn", "Ǧahr beim Ṣād und Hams beim Sīn", "Šidda beim Ṣād und Raḫāwa beim Sīn", "Tafaššī beim Ṣād und Ṣafīr beim Sīn"], "Ṣād ist gehoben und eingeschlossen, Sīn gesenkt und offen. Darum wird ein Ṣād mit schwachem Iṭbāq zum Sīn, wie Sībawaih bemerkte."],
    ar: ["تشترك الصاد والسين في المخرج والهمس والرخاوة والصفير، فما الذي يفرق بينهما؟", ["الاستعلاء والإطباق في الصاد، والاستفال والانفتاح في السين", "الجهر في الصاد والهمس في السين", "الشدة في الصاد والرخاوة في السين", "التفشي في الصاد والصفير في السين"], "الصاد مستعلية مطبقة، والسين مستفلة منفتحة، ولذلك تصير الصاد سينًا إذا ضعف إطباقها كما نبّه سيبويه."] },

  { id: "tjm-059", s: "tajweed", g: 3, d: 3, t: ["sifat", "itbaq", "istila-istifal"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["Dhāl and ẓāʾ share makhraj, jahr and rakhāwa. What separates them?", ["Istiʿlāʾ and iṭbāq in ẓāʾ, istifāl and infitāḥ in dhāl", "Hams in dhāl and jahr in ẓāʾ", "Istiṭāla in ẓāʾ only", "Qalqala in ẓāʾ only"], "Ẓāʾ is raised and enclosed, dhāl lowered and open; otherwise they are alike. Istiṭāla belongs to ḍād, and neither letter has qalqala."],
    de: ["Ḏāl und Ẓāʾ teilen Stelle, Ǧahr und Raḫāwa. Was trennt sie?", ["Istiʿlāʾ und Iṭbāq beim Ẓāʾ, Istifāl und Infitāḥ beim Ḏāl", "Hams beim Ḏāl und Ǧahr beim Ẓāʾ", "Istiṭāla nur beim Ẓāʾ", "Qalqala nur beim Ẓāʾ"], "Ẓāʾ ist gehoben und eingeschlossen, Ḏāl gesenkt und offen; sonst gleichen sie sich. Istiṭāla gehört zum Ḍād, und keiner der beiden hat Qalqala."],
    ar: ["تشترك الذال والظاء في المخرج والجهر والرخاوة، فما الذي يفرق بينهما؟", ["الاستعلاء والإطباق في الظاء، والاستفال والانفتاح في الذال", "الهمس في الذال والجهر في الظاء", "الاستطالة في الظاء وحدها", "القلقلة في الظاء وحدها"], "الظاء مستعلية مطبقة والذال مستفلة منفتحة، وما عدا ذلك متفق. أما الاستطالة فللضاد، ولا قلقلة في أيٍّ منهما."] },

  { id: "tjm-060", s: "tajweed", g: 2, d: 2, t: ["sifat", "hams-jahr"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["Thāʾ and dhāl share their makhraj. Which attribute separates them?", ["Hams in thāʾ and jahr in dhāl", "Shidda in thāʾ and rakhāwa in dhāl", "Istiʿlāʾ in dhāl and istifāl in thāʾ", "Ṣafīr in thāʾ only"], "Thāʾ is mahmūs and dhāl majhūr; all their other attributes agree. A thāʾ voiced without breath therefore sounds like dhāl."],
    de: ["Ṯāʾ und Ḏāl haben dieselbe Stelle. Welche Eigenschaft trennt sie?", ["Hams beim Ṯāʾ und Ǧahr beim Ḏāl", "Šidda beim Ṯāʾ und Raḫāwa beim Ḏāl", "Istiʿlāʾ beim Ḏāl und Istifāl beim Ṯāʾ", "Ṣafīr nur beim Ṯāʾ"], "Ṯāʾ ist mahmūs, Ḏāl maǧhūr; alle anderen Eigenschaften stimmen überein. Ein ohne Atem stimmhaft gesprochenes Ṯāʾ klingt daher wie Ḏāl."],
    ar: ["الثاء والذال من مخرج واحد، فما الصفة التي تفرق بينهما؟", ["الهمس في الثاء والجهر في الذال", "الشدة في الثاء والرخاوة في الذال", "الاستعلاء في الذال والاستفال في الثاء", "الصفير في الثاء وحدها"], "الثاء مهموسة والذال مجهورة، وسائر صفاتهما متفقة، فإذا حُبس النفس مع الثاء صارت ذالًا."] },

  { id: "tjm-061", s: "tajweed", g: 4, d: 5, t: ["sifat", "makharij-halq", "hams-jahr"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["ʿAyn and ḥāʾ both come from the middle of the throat. Which description of their attributes is correct?", ["ʿAyn has jahr and tawassuṭ; ḥāʾ has hams and rakhāwa", "ʿAyn has hams and shidda; ḥāʾ has jahr and rakhāwa", "Both have jahr; only ʿayn has tawassuṭ", "Both have rakhāwa; only ḥāʾ has istiʿlāʾ"], "ʿAyn is majhūr and one of the 'lin ʿumar' letters; ḥāʾ is mahmūs and rikhw. Both are mustafil, munfatiḥ and muṣmat. If the breath is held with ḥāʾ it drifts toward ʿayn."],
    de: ["ʿAin und Ḥāʾ kommen beide aus der Mitte der Kehle. Welche Beschreibung ihrer Eigenschaften ist richtig?", ["ʿAin hat Ǧahr und Tawassuṭ, Ḥāʾ hat Hams und Raḫāwa", "ʿAin hat Hams und Šidda, Ḥāʾ hat Ǧahr und Raḫāwa", "Beide haben Ǧahr, nur ʿAin hat Tawassuṭ", "Beide haben Raḫāwa, nur Ḥāʾ hat Istiʿlāʾ"], "ʿAin ist maǧhūr und gehört zu „lin ʿumar“; Ḥāʾ ist mahmūs und riḫw. Beide sind mustafil, munfatiḥ und muṣmat. Hält man beim Ḥāʾ den Atem zurück, nähert es sich dem ʿAin."],
    ar: ["العين والحاء من وسط الحلق، فأيُّ وصف لصفاتهما صحيح؟", ["العين مجهورة متوسطة، والحاء مهموسة رخوة", "العين مهموسة شديدة، والحاء مجهورة رخوة", "كلتاهما مجهورة، وتنفرد العين بالتوسط", "كلتاهما رخوة، وتنفرد الحاء بالاستعلاء"], "العين مجهورة من حروف «لن عمر»، والحاء مهموسة رخوة، وكلتاهما مستفلة منفتحة مصمتة. فإذا حُبس النفس مع الحاء قربت من العين."] },

  { id: "tjm-062", s: "tajweed", g: 4, d: 4, t: ["sifat", "makharij-halq", "hams-jahr"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["Ghayn and khāʾ share makhraj, rakhāwa, istiʿlāʾ, infitāḥ and iṣmāt. What is the only paired attribute that separates them?", ["Jahr in ghayn and hams in khāʾ", "Iṭbāq in khāʾ and infitāḥ in ghayn", "Shidda in ghayn and rakhāwa in khāʾ", "Istifāl in ghayn and istiʿlāʾ in khāʾ"], "Ghayn is majhūr and khāʾ mahmūs; in every other paired attribute they agree. Neither is muṭbaq, and both are mustaʿlī."],
    de: ["Ġain und Ḫāʾ teilen Stelle, Raḫāwa, Istiʿlāʾ, Infitāḥ und Iṣmāt. Welche paarige Eigenschaft trennt sie als einzige?", ["Ǧahr beim Ġain und Hams beim Ḫāʾ", "Iṭbāq beim Ḫāʾ und Infitāḥ beim Ġain", "Šidda beim Ġain und Raḫāwa beim Ḫāʾ", "Istifāl beim Ġain und Istiʿlāʾ beim Ḫāʾ"], "Ġain ist maǧhūr, Ḫāʾ mahmūs; in allen anderen paarigen Eigenschaften stimmen sie überein. Keiner ist muṭbaq, beide sind mustaʿlī."],
    ar: ["تشترك الغين والخاء في المخرج والرخاوة والاستعلاء والانفتاح والإصمات، فما الصفة المتضادة الوحيدة التي تفرق بينهما؟", ["الجهر في الغين والهمس في الخاء", "الإطباق في الخاء والانفتاح في الغين", "الشدة في الغين والرخاوة في الخاء", "الاستفال في الغين والاستعلاء في الخاء"], "الغين مجهورة والخاء مهموسة، وتتفقان في سائر الصفات المتضادة؛ فلا إطباق في أيٍّ منهما، وكلتاهما مستعلية."] },

  { id: "tjm-063", s: "tajweed", g: 4, d: 4, t: ["sifat", "itbaq", "hams-jahr"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on ṣifāt al-ḥurūf",
    en: ["Which is the only muṭbaq letter that is also mahmūs?", ["Ṣād", "Ṭāʾ", "Ḍād", "Ẓāʾ"], "Of the four iṭbāq letters, only ṣād appears in 'fa-ḥaththahu shakhṣun sakat'. Ṭāʾ, ḍād and ẓāʾ are majhūr."],
    de: ["Welcher ist der einzige muṭbaq-Buchstabe, der zugleich mahmūs ist?", ["Ṣād", "Ṭāʾ", "Ḍād", "Ẓāʾ"], "Von den vier Iṭbāq-Buchstaben steht nur Ṣād in „fa-ḥaṯṯahu šaḫṣun sakat“. Ṭāʾ, Ḍād und Ẓāʾ sind maǧhūr."],
    ar: ["ما الحرف المطبق الوحيد الذي هو مهموس أيضًا؟", ["الصاد", "الطاء", "الضاد", "الظاء"], "من حروف الإطباق الأربعة لا يوجد في «فحثه شخص سكت» إلا الصاد، أما الطاء والضاد والظاء فمجهورة."] },

  // ---------- Waqf and ibtidāʾ ----------
  { id: "tjm-064", s: "tajweed", g: 1, d: 1, t: ["waqf", "definitions"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on waqf and ibtidāʾ",
    en: ["What is waqf in recitation?", ["Cutting the sound at the end of a word long enough to breathe, intending to continue", "Pausing briefly without taking a breath, then continuing", "Ending the recitation altogether and turning to something else", "Starting the recitation again after a break"], "Ibn al-Jazarī defines waqf as cutting off the voice on a word for a time in which one usually breathes, with the intention of resuming. A pause without breath is sakt; ending the recitation is qaṭʿ."],
    de: ["Was ist Waqf in der Rezitation?", ["Den Laut am Wortende so lange unterbrechen, dass man atmen kann, mit der Absicht weiterzulesen", "Kurz innehalten, ohne Atem zu holen, und dann weiterlesen", "Die Rezitation ganz beenden und sich etwas anderem zuwenden", "Nach einer Unterbrechung die Rezitation neu beginnen"], "Ibn al-Ǧazarī definiert Waqf als Unterbrechung der Stimme auf einem Wort für die Zeit eines gewöhnlichen Atemzugs, mit der Absicht weiterzulesen. Ein Innehalten ohne Atem ist Sakt, das Beenden der Rezitation Qaṭʿ."],
    ar: ["ما الوقف في القراءة؟", ["قطع الصوت على آخر الكلمة زمنًا يُتنفس فيه عادةً بنية استئناف القراءة", "قطع الصوت زمنًا يسيرًا دون تنفس ثم مواصلة القراءة", "قطع القراءة بالكلية والانتقال إلى غيرها", "الشروع في القراءة بعد انقطاع"], "عرّف ابن الجزري الوقف بأنه قطع الصوت على الكلمة زمنًا يُتنفس فيه عادة بنية استئناف القراءة. أما القطع دون تنفس فالسكت، وأما ترك القراءة فالقطع."] },

  { id: "tjm-065", s: "tajweed", g: 2, d: 2, t: ["waqf", "sakt", "definitions"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on waqf and ibtidāʾ",
    en: ["What is sakt?", ["A short pause of about two counts without taking a breath", "A stop of normal length with a breath", "Ending the recitation and seeking refuge again later", "Joining the end of a word to the next without any pause"], "Sakt is a brief cut of the voice, usually estimated at two counts, without breathing. It is transmitted at specific places only and is not left to the reciter's choice."],
    de: ["Was ist Sakt?", ["Ein kurzes Innehalten von etwa zwei Zählzeiten ohne Atemholen", "Ein Anhalten gewöhnlicher Länge mit Atemholen", "Das Beenden der Rezitation mit erneuter Istiʿāḏa später", "Das Verbinden des Wortendes mit dem nächsten Wort ohne jede Pause"], "Sakt ist eine kurze Unterbrechung der Stimme, meist auf zwei Zählzeiten geschätzt, ohne zu atmen. Es ist nur an bestimmten Stellen überliefert und nicht der freien Wahl des Rezitators überlassen."],
    ar: ["ما السكت؟", ["قطع الصوت زمنًا يسيرًا قدره حركتان عادةً من غير تنفس", "قطع الصوت زمنًا يُتنفس فيه عادة", "ترك القراءة ثم الاستعاذة عند العودة إليها", "وصل آخر الكلمة بما بعدها دون أي قطع"], "السكت قطع الصوت زمنًا دون زمن الوقف عادةً من غير تنفس، ويُقدَّر غالبًا بحركتين، وهو مقيد بالرواية في مواضع مخصوصة."] },

  { id: "tjm-066", s: "tajweed", g: 1, d: 2, t: ["waqf", "waqf-intent"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on waqf and ibtidāʾ",
    en: ["A reciter runs out of breath, coughs or sneezes and has to stop. What is this kind of stop called?", ["Iḍṭirārī (forced)", "Ikhtiyārī (chosen)", "Ikhtibārī (for testing)", "Intiẓārī (waiting)"], "A stop caused by necessity, such as shortness of breath, a cough, a sneeze or forgetting, is iḍṭirārī. It is allowed on any word, but the reciter then resumes from a place that gives sound meaning."],
    de: ["Einem Rezitator geht der Atem aus, er hustet oder niest und muss anhalten. Wie heißt diese Art des Anhaltens?", ["Iḍṭirārī (erzwungen)", "Iḫtiyārī (gewählt)", "Iḫtibārī (zur Prüfung)", "Intiẓārī (abwartend)"], "Ein Anhalten aus Not, etwa wegen Atemnot, Husten, Niesen oder Vergessen, ist iḍṭirārī. Es ist auf jedem Wort erlaubt, doch der Rezitator setzt danach an einer sinnvollen Stelle wieder ein."],
    ar: ["انقطع نفَس القارئ أو سعل أو عطس فاضطر إلى الوقف، فما اسم هذا الوقف؟", ["اضطراري", "اختياري", "اختباري", "انتظاري"], "الوقف الاضطراري ما يعرض للقارئ لضرورة كضيق النفس والسعال والعطاس والنسيان، ويجوز على أي كلمة، ثم يبتدئ القارئ بما يصح معناه."] },

  { id: "tjm-067", s: "tajweed", g: 2, d: 2, t: ["waqf", "waqf-intent"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on waqf and ibtidāʾ",
    en: ["A teacher asks a student to stop on a word that is not normally a place of stopping, to check how it is stopped on according to its written form. What is this stop called?", ["Ikhtibārī", "Iḍṭirārī", "Intiẓārī", "Tāmm"], "Ikhtibārī comes from ikhtibār (testing): the stop serves teaching or examination, for example to show whether a word ends in tāʾ maftūḥa or marbūṭa. It is not a stop for meaning."],
    de: ["Ein Lehrer lässt einen Schüler auf einem Wort anhalten, das gewöhnlich kein Haltepunkt ist, um zu prüfen, wie man es nach seiner Schreibung anhält. Wie heißt dieses Anhalten?", ["Iḫtibārī", "Iḍṭirārī", "Intiẓārī", "Tāmm"], "Iḫtibārī kommt von Iḫtibār (Prüfung): Das Anhalten dient dem Unterricht oder der Prüfung, etwa um zu zeigen, ob ein Wort mit offenem oder gebundenem Tāʾ endet. Es ist kein Anhalten um des Sinnes willen."],
    ar: ["طلب المعلم من الطالب أن يقف على كلمة ليست موضع وقف عادةً ليختبره في كيفية الوقف عليها بحسب رسمها، فما اسم هذا الوقف؟", ["اختباري", "اضطراري", "انتظاري", "تام"], "الوقف الاختباري ما يكون للتعليم أو الامتحان، كبيان ما رُسم بالتاء المفتوحة أو المربوطة، وليس وقفًا لتمام المعنى."] },

  { id: "tjm-068", s: "tajweed", g: 3, d: 3, t: ["waqf", "waqf-intent"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on waqf and ibtidāʾ",
    en: ["In which situation does the intiẓārī stop occur?", ["When a reciter combining several readings stops on a word to complete its other readings", "When a reciter waits for the listeners to settle before beginning", "When a reciter waits at a sign of muʿānaqa to choose one of the two places", "When an imam pauses for the congregation to say āmīn"], "Intiẓārī belongs to jamʿ al-qirāʾāt: the reciter stops on a word where readings differ, then repeats it with the remaining readings before moving on."],
    de: ["In welcher Situation kommt das Intiẓārī-Anhalten vor?", ["Wenn ein Rezitator, der mehrere Lesarten verbindet, auf einem Wort anhält, um dessen übrige Lesarten nachzuholen", "Wenn ein Rezitator wartet, bis die Zuhörer zur Ruhe kommen", "Wenn ein Rezitator an einem Muʿānaqa-Zeichen wartet, um eine der beiden Stellen zu wählen", "Wenn ein Imam innehält, damit die Gemeinde Āmīn sagt"], "Intiẓārī gehört zum Ǧamʿ al-Qirāʾāt: Der Rezitator hält auf einem Wort mit abweichenden Lesarten an und wiederholt es mit den übrigen Lesarten, bevor er weiterliest."],
    ar: ["في أيِّ حال يكون الوقف الانتظاري؟", ["حين يقف القارئ الجامع للقراءات على كلمة ليستوفي ما فيها من أوجه الخلاف", "حين ينتظر القارئ سكون السامعين قبل البدء", "حين يتريث القارئ عند علامة التعانق ليختار أحد الموضعين", "حين يسكت الإمام ليؤمّن المأمومون"], "الوقف الانتظاري خاص بجمع القراءات، يقف فيه القارئ على الكلمة القرآنية التي فيها خلاف ليعطفها بباقي الأوجه ثم يمضي."] },

  { id: "tjm-069", s: "tajweed", g: 2, d: 3, t: ["waqf", "waqf-types"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on waqf and ibtidāʾ",
    en: ["How is the waqf tāmm (complete stop) defined?", ["A stop where what follows has no connection with what precedes, neither in wording nor in meaning", "A stop where what follows is connected in meaning but not in grammar", "A stop where what follows is connected in grammar, so one goes back to continue", "A stop where the words before it give no useful meaning"], "At a tāmm stop the passage is finished in both structure and sense, often at the end of a story or topic; one stops and begins with what follows. The other descriptions are kāfī, ḥasan and qabīḥ."],
    de: ["Wie wird das Waqf tāmm (vollständiges Anhalten) definiert?", ["Ein Anhalten, nach dem das Folgende weder im Wortlaut noch in der Bedeutung mit dem Vorigen zusammenhängt", "Ein Anhalten, nach dem das Folgende in der Bedeutung, aber nicht grammatisch zusammenhängt", "Ein Anhalten, nach dem das Folgende grammatisch zusammenhängt, sodass man zurückgeht", "Ein Anhalten, bei dem das Vorige keinen brauchbaren Sinn ergibt"], "Beim Tāmm ist die Stelle in Bau und Sinn abgeschlossen, oft am Ende einer Geschichte oder eines Themas; man hält an und beginnt mit dem Folgenden. Die übrigen Beschreibungen sind Kāfī, Ḥasan und Qabīḥ."],
    ar: ["ما تعريف الوقف التام؟", ["الوقف على ما لا تعلق لما بعده به لا لفظًا ولا معنى", "الوقف على ما تعلق ما بعده به معنى لا لفظًا", "الوقف على ما تعلق ما بعده به لفظًا فيُعاد إليه عند الوصل", "الوقف على ما لا يُفهم منه معنى صحيح"], "الوقف التام ما تم معناه ولم يتعلق بما بعده لفظًا ولا معنى، ويكثر عند انقضاء القصص ورؤوس الآي، فيُوقف عليه ويُبتدأ بما بعده. والتعريفات الأخرى للكافي والحسن والقبيح."] },

  { id: "tjm-070", s: "tajweed", g: 2, d: 3, t: ["waqf", "waqf-types"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on waqf and ibtidāʾ",
    en: ["How is the waqf kāfī (sufficient stop) defined?", ["What follows is connected with it in meaning only, not in grammatical structure", "What follows has no connection with it at all", "What follows is connected with it in grammatical structure", "The stop is only allowed at the end of a verse"], "In the kāfī stop the sentence is grammatically complete, but the next sentence still continues the same subject. One may stop and begin with what follows, as with tāmm."],
    de: ["Wie wird das Waqf kāfī (ausreichendes Anhalten) definiert?", ["Das Folgende hängt nur in der Bedeutung damit zusammen, nicht im grammatischen Bau", "Das Folgende hängt überhaupt nicht damit zusammen", "Das Folgende hängt im grammatischen Bau damit zusammen", "Das Anhalten ist nur am Versende erlaubt"], "Beim Kāfī ist der Satz grammatisch vollständig, doch der folgende Satz setzt dasselbe Thema fort. Man darf anhalten und mit dem Folgenden beginnen, wie beim Tāmm."],
    ar: ["ما تعريف الوقف الكافي؟", ["الوقف على ما تعلق ما بعده به معنى لا لفظًا", "الوقف على ما لا تعلق لما بعده به أصلًا", "الوقف على ما تعلق ما بعده به لفظًا", "الوقف الذي لا يجوز إلا على رؤوس الآي"], "الوقف الكافي ما تم لفظه وتعلق ما بعده به من جهة المعنى فقط، فيحسن الوقف عليه والابتداء بما بعده كالتام."] },

  { id: "tjm-071", s: "tajweed", g: 3, d: 3, t: ["waqf", "waqf-types", "ibtida"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on waqf and ibtidāʾ",
    en: ["A reciter makes a ḥasan stop in the middle of a verse. How should he resume?", ["Go back to the word he stopped on, or before it, and join it with what follows", "Begin directly with the next word, as after a tāmm stop", "Skip the next word and begin with the following sentence", "Repeat only the last letter of the word before continuing"], "A ḥasan stop gives a sound meaning, but what follows is grammatically tied to it, so beginning with it is not good. Except at a verse end, the reciter returns and connects."],
    de: ["Ein Rezitator macht mitten im Vers ein Ḥasan-Anhalten. Wie soll er fortfahren?", ["Zum Wort, auf dem er anhielt, oder davor zurückgehen und es mit dem Folgenden verbinden", "Direkt mit dem nächsten Wort beginnen, wie nach einem Tāmm", "Das nächste Wort überspringen und mit dem folgenden Satz beginnen", "Nur den letzten Buchstaben des Wortes wiederholen und weiterlesen"], "Ein Ḥasan-Anhalten ergibt einen gültigen Sinn, doch das Folgende ist grammatisch daran gebunden, daher ist es nicht gut, damit zu beginnen. Außer am Versende geht der Rezitator zurück und verbindet."],
    ar: ["وقف القارئ وقفًا حسنًا في أثناء آية، فكيف يستأنف؟", ["يعود إلى الكلمة الموقوف عليها أو ما قبلها فيصلها بما بعدها", "يبتدئ بالكلمة التالية مباشرة كما بعد الوقف التام", "يتجاوز الكلمة التالية ويبتدئ بالجملة التي بعدها", "يعيد الحرف الأخير من الكلمة ثم يمضي"], "الوقف الحسن يفيد معنى صحيحًا لكن ما بعده متعلق به لفظًا، فلا يحسن الابتداء به، فيعود القارئ ويصل، إلا إذا كان رأس آية."] },

  { id: "tjm-072", s: "tajweed", g: 1, d: 2, t: ["waqf", "waqf-types"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on waqf and ibtidāʾ",
    en: ["What is a waqf qabīḥ (repugnant stop)?", ["A stop on words that give no complete meaning or that suggest a wrong meaning", "A stop at the end of a verse whose meaning continues", "A stop where the next sentence starts a new topic", "A stop made because the reciter ran out of breath"], "A stop is qabīḥ when the words before it make no sense on their own, or worse, when they suggest a meaning that is wrong or improper. Such a stop is only excused by necessity, after which the reciter goes back."],
    de: ["Was ist ein Waqf qabīḥ (verwerfliches Anhalten)?", ["Ein Anhalten auf Worten, die keinen vollständigen oder einen falschen Sinn ergeben", "Ein Anhalten am Versende, dessen Sinn sich fortsetzt", "Ein Anhalten, nach dem der nächste Satz ein neues Thema beginnt", "Ein Anhalten, weil dem Rezitator der Atem ausging"], "Ein Anhalten ist qabīḥ, wenn das Vorige für sich keinen Sinn ergibt oder, schlimmer, einen falschen oder unpassenden Sinn nahelegt. Entschuldigt ist es nur aus Not, und dann geht der Rezitator zurück."],
    ar: ["ما الوقف القبيح؟", ["الوقف على ما لا يتم به معنى أو ما يوهم معنى فاسدًا", "الوقف على رأس آية يتصل معناها بما بعدها", "الوقف على ما يبدأ بعده موضوع جديد", "الوقف لانقطاع النفس"], "الوقف القبيح ما لا يُفهم منه معنى، وأقبح منه ما أوهم معنى فاسدًا أو غير لائق، ولا يجوز تعمده إلا لضرورة، ثم يعود القارئ ويصل."] },

  { id: "tjm-073", s: "tajweed", g: 4, d: 5, t: ["waqf", "waqf-types"], src: "Ibn al-Jazarī, al-Muqaddima al-Jazariyya, section on waqf and ibtidāʾ",
    en: ["What does Ibn al-Jazarī state in the Muqaddima about obligatory and forbidden stops in the Quran?", ["No stop is obligatory or forbidden in itself; only a reason, such as distorting the meaning, makes it so", "Every stop marked in the muṣḥaf is obligatory and every unmarked one forbidden", "Stopping at the end of every verse is obligatory and in the middle forbidden", "The mīm sign makes a stop obligatory in the sense of fiqh, so leaving it is sinful"], "Ibn al-Jazarī says there is no stop in the Quran that is wājib, nor one that is ḥarām, except what has a cause. 'Lāzim' in the mīm sign is a technical term of the qurrāʾ; connecting there is not a sin in itself unless one intends the wrong meaning."],
    de: ["Was sagt Ibn al-Ǧazarī in der Muqaddima über verpflichtendes und verbotenes Anhalten im Koran?", ["Kein Anhalten ist an sich Pflicht oder verboten; nur ein Grund, etwa die Entstellung des Sinnes, macht es dazu", "Jedes im Muṣḥaf markierte Anhalten ist Pflicht, jedes unmarkierte verboten", "Das Anhalten an jedem Versende ist Pflicht, in der Versmitte verboten", "Das Mīm-Zeichen macht das Anhalten im Sinne des Fiqh zur Pflicht, sein Unterlassen ist Sünde"], "Ibn al-Ǧazarī sagt, es gebe im Koran kein Anhalten, das wāǧib oder ḥarām sei, außer aus einem Grund. „Lāzim“ beim Mīm-Zeichen ist ein Fachbegriff der Rezitatoren; das Verbinden dort ist an sich keine Sünde, außer man beabsichtigt den falschen Sinn."],
    ar: ["ماذا قرر ابن الجزري في المقدمة بشأن الوقف الواجب والحرام في القرآن؟", ["ليس في القرآن وقف واجب ولا حرام إلا ما كان له سبب كإيهام معنى فاسد", "كل وقف معلَّم في المصحف واجب، وكل ما لم يُعلَّم حرام", "الوقف على رأس كل آية واجب، وفي وسطها حرام", "علامة الميم توجب الوقف وجوبًا شرعيًّا يأثم تاركه"], "قال ابن الجزري: وليس في القرآن من وقفٍ وجب، ولا حرامٌ غير ما له سبب. فاللزوم في علامة الميم اصطلاح للقراء، ولا يأثم الواصل إلا إن قصد المعنى الفاسد."] },

  { id: "tjm-074", s: "tajweed", g: 4, d: 4, t: ["waqf", "ruus-al-ay"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on waqf and ibtidāʾ",
    en: ["What view did many scholars, including Ibn al-Jazarī, hold about stopping at the end of a verse whose meaning continues into the next?", ["Stopping there is permitted and even sunna, based on the hadith of Umm Salama on the Prophet's verse-by-verse recitation", "Stopping there is qabīḥ, so the reciter must always connect", "Stopping there is allowed only in prayer, never outside it", "Stopping there obliges the reciter to repeat the last word before continuing"], "The hadith of Umm Salama, reported by Abū Dāwūd and al-Tirmidhī, describes the Prophet's recitation as stopping verse by verse. On this basis many held that stopping at verse ends is sunna even where the meaning continues; others preferred to connect where the link is very close."],
    de: ["Welche Ansicht vertraten viele Gelehrte, darunter Ibn al-Ǧazarī, über das Anhalten am Ende eines Verses, dessen Sinn sich im nächsten fortsetzt?", ["Das Anhalten ist erlaubt und sogar Sunna, gestützt auf den Hadith von Umm Salama über die versweise Rezitation des Propheten", "Das Anhalten ist qabīḥ, daher muss man immer verbinden", "Das Anhalten ist nur im Gebet erlaubt, außerhalb nie", "Das Anhalten verpflichtet, das letzte Wort vor dem Weiterlesen zu wiederholen"], "Der Hadith von Umm Salama bei Abū Dāwūd und at-Tirmiḏī beschreibt, dass der Prophet Vers für Vers anhielt. Daraus folgerten viele, dass das Anhalten an Versenden Sunna ist, auch wenn der Sinn weitergeht; andere zogen das Verbinden vor, wo der Zusammenhang sehr eng ist."],
    ar: ["ما الرأي الذي ذهب إليه كثير من العلماء ومنهم ابن الجزري في الوقف على رأس آية يتصل معناها بما بعدها؟", ["أنه جائز بل سنة؛ استنادًا إلى حديث أم سلمة في تقطيع النبي قراءته آية آية", "أنه وقف قبيح فيجب الوصل دائمًا", "أنه جائز في الصلاة دون غيرها", "أنه يوجب إعادة الكلمة الأخيرة قبل المواصلة"], "حديث أم سلمة عند أبي داود والترمذي في وصف قراءة النبي وأنه كان يقطّعها آية آية، فذهب كثيرون إلى أن الوقف على رؤوس الآي سنة وإن تعلق ما بعدها بها، واختار آخرون الوصل حيث اشتد التعلق."] },

  { id: "tjm-075", s: "tajweed", g: 3, d: 4, t: ["ibtida", "waqf-intent"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on waqf and ibtidāʾ",
    en: ["Why do the scholars say that ibtidāʾ (starting) can only be ikhtiyārī?", ["Because, unlike stopping, no necessity such as running out of breath forces the reciter to start at a particular word", "Because starting is always at the beginning of a sūra", "Because the muṣḥaf signs mark every permitted starting point", "Because starting after a stop needs the istiʿādha every time"], "Ibn al-Jazarī notes that a stop may be forced, but a start never is: the reciter can always choose where to begin. Therefore he must begin only where the meaning is sound and complete."],
    de: ["Warum sagen die Gelehrten, dass Ibtidāʾ (Beginnen) nur iḫtiyārī sein kann?", ["Weil, anders als beim Anhalten, keine Not wie Atemmangel dazu zwingt, an einem bestimmten Wort zu beginnen", "Weil man immer am Anfang einer Sure beginnt", "Weil die Zeichen im Muṣḥaf jeden erlaubten Beginn markieren", "Weil man nach jedem Anhalten die Istiʿāḏa sprechen muss"], "Ibn al-Ǧazarī bemerkt, dass das Anhalten erzwungen sein kann, der Beginn aber nie: Der Rezitator kann stets wählen, wo er einsetzt. Darum darf er nur dort beginnen, wo der Sinn richtig und vollständig ist."],
    ar: ["لماذا قال العلماء إن الابتداء لا يكون إلا اختياريًّا؟", ["لأنه بخلاف الوقف لا تُلجئ إليه ضرورة كانقطاع النفس، فللقارئ أن يختار موضعه", "لأن الابتداء لا يكون إلا من أول السورة", "لأن علامات المصحف تبيّن كل موضع يجوز الابتداء به", "لأن الابتداء بعد كل وقف يحتاج إلى استعاذة"], "قال ابن الجزري: الابتداء لا يكون إلا اختياريًّا؛ لأنه ليس كالوقف تدعو إليه ضرورة، فلا يجوز إلا بمستقل بالمعنى موفٍ بالمقصود."] },

  { id: "tjm-076", s: "tajweed", g: 4, d: 5, t: ["waqf", "waqf-books"], src: "Abū ʿAmr al-Dānī, al-Muktafā fī al-Waqf wa-l-Ibtidāʾ",
    en: ["Which work of Abū ʿAmr al-Dānī is devoted to waqf and ibtidāʾ?", ["al-Muktafā", "al-Taysīr", "al-Muqniʿ", "Jāmiʿ al-Bayān"], "Al-Muktafā fī al-Waqf wa-l-Ibtidāʾ classifies the stops of the Quran as tāmm, kāfī and ḥasan. Al-Taysīr and Jāmiʿ al-Bayān deal with the readings and al-Muqniʿ with the rasm of the muṣḥaf."],
    de: ["Welches Werk von Abū ʿAmr ad-Dānī ist Waqf und Ibtidāʾ gewidmet?", ["al-Muktafā", "at-Taisīr", "al-Muqniʿ", "Ǧāmiʿ al-Bayān"], "Al-Muktafā fī al-Waqf wa-l-Ibtidāʾ ordnet die Haltestellen des Korans als tāmm, kāfī und ḥasan ein. At-Taisīr und Ǧāmiʿ al-Bayān behandeln die Lesarten, al-Muqniʿ die Schreibung (Rasm) des Muṣḥaf."],
    ar: ["ما كتاب أبي عمرو الداني المخصص للوقف والابتداء؟", ["المكتفى", "التيسير", "المقنع", "جامع البيان"], "كتاب «المكتفى في الوقف والابتدا» صنّف فيه الداني الوقوف إلى تام وكافٍ وحسن، أما «التيسير» و«جامع البيان» ففي القراءات، و«المقنع» في رسم المصحف."] },

  { id: "tjm-077", s: "tajweed", g: 4, d: 5, t: ["waqf-signs", "waqf-books"], src: "al-Sajāwandī, ʿIlal al-Wuqūf; al-Suyūṭī, al-Itqān, ch. on waqf and ibtidāʾ",
    en: ["The system of stop symbols such as mīm, ṭāʾ, jīm, zāy and ṣād, still used in many South Asian muṣḥafs, goes back to which scholar?", ["al-Sajāwandī", "al-Ashmūnī", "Ibn al-Anbārī", "al-Naḥḥās"], "Muḥammad ibn Ṭayfūr al-Sajāwandī classified the stops and gave each class a letter symbol. Al-Ashmūnī, Ibn al-Anbārī and al-Naḥḥās also wrote on waqf, but the letter system is his."],
    de: ["Auf welchen Gelehrten geht das System der Haltezeichen wie Mīm, Ṭāʾ, Ǧīm, Zāy und Ṣād zurück, das in vielen südasiatischen Muṣḥafs noch verwendet wird?", ["Auf as-Saǧāwandī", "Auf al-Ušmūnī", "Auf Ibn al-Anbārī", "Auf an-Naḥḥās"], "Muḥammad ibn Ṭaifūr as-Saǧāwandī teilte die Haltestellen in Klassen ein und gab jeder ein Buchstabenzeichen. Al-Ušmūnī, Ibn al-Anbārī und an-Naḥḥās schrieben ebenfalls über Waqf, das Buchstabensystem stammt aber von ihm."],
    ar: ["إلى أيِّ عالم يعود نظام رموز الوقف كالميم والطاء والجيم والزاي والصاد، المستعمل في كثير من مصاحف شبه القارة الهندية؟", ["السجاوندي", "الأشموني", "ابن الأنباري", "النحاس"], "قسّم محمد بن طيفور السجاوندي الوقوف أنواعًا وجعل لكل نوع رمزًا من الحروف، وللأشموني وابن الأنباري والنحاس كتب في الوقف، لكن هذا النظام للسجاوندي."] },

  // ---------- Stop signs of the muṣḥaf ----------
  { id: "tjm-078", s: "tajweed", g: 1, d: 1, t: ["waqf-signs", "waqf-lazim"], src: "Madina Muṣḥaf (King Fahd Complex), explanatory note on the stop signs",
    en: ["In the Madina Muṣḥaf, what does a small mīm above the text indicate?", ["A necessary stop (waqf lāzim), because connecting could suggest a wrong meaning", "A prohibited stop, so the reader must connect", "A stop that is allowed, with connecting preferred", "A short pause without breath"], "The mīm marks waqf lāzim: connecting there could make the next words seem to belong to the previous sentence and so distort the meaning. The other descriptions belong to lā, ṣilā and the sakt sign."],
    de: ["Was bedeutet im Madina-Muṣḥaf ein kleines Mīm über dem Text?", ["Ein notwendiges Anhalten (Waqf lāzim), weil das Verbinden einen falschen Sinn nahelegen könnte", "Ein verbotenes Anhalten, man muss verbinden", "Ein erlaubtes Anhalten, wobei das Verbinden besser ist", "Ein kurzes Innehalten ohne Atem"], "Das Mīm kennzeichnet Waqf lāzim: Beim Verbinden könnten die folgenden Worte zum vorigen Satz zu gehören scheinen und den Sinn entstellen. Die anderen Beschreibungen gehören zu Lā, Ṣilā und dem Sakt-Zeichen."],
    ar: ["ماذا تعني الميم الصغيرة فوق الكلمة في مصحف المدينة؟", ["الوقف اللازم؛ لأن الوصل قد يوهم معنى غير مراد", "الوقف الممنوع فيجب الوصل", "الوقف الجائز مع أولوية الوصل", "سكتة لطيفة من غير تنفس"], "الميم علامة الوقف اللازم، إذ لو وُصل الكلام لأوهم أن ما بعده من تمام ما قبله فيفسد المعنى. أما الأوصاف الأخرى فلعلامات «لا» و«صلى» والسكت."] },

  { id: "tjm-079", s: "tajweed", g: 1, d: 2, t: ["waqf-signs"], src: "Madina Muṣḥaf (King Fahd Complex), explanatory note on the stop signs",
    en: ["In the Madina Muṣḥaf, what does the sign lā above a word indicate?", ["Do not stop here; if forced to stop, go back and connect", "Stopping here is necessary to avoid a wrong meaning", "Stopping and connecting are equally good here", "Stop on one of two nearby places, not both"], "Lā marks a prohibited stop (waqf mamnūʿ): the next words are tied to it. If a reciter stops there out of necessity, he resumes from the word itself or before it."],
    de: ["Was bedeutet im Madina-Muṣḥaf das Zeichen Lā über einem Wort?", ["Hier nicht anhalten; wer gezwungen anhält, geht zurück und verbindet", "Hier ist Anhalten notwendig, um einen falschen Sinn zu vermeiden", "Anhalten und Verbinden sind hier gleich gut", "Auf einer von zwei nahen Stellen anhalten, nicht auf beiden"], "Lā kennzeichnet ein untersagtes Anhalten (Waqf mamnūʿ): Die folgenden Worte sind daran gebunden. Hält ein Rezitator dort aus Not an, setzt er beim Wort selbst oder davor wieder ein."],
    ar: ["ماذا تعني علامة «لا» فوق الكلمة في مصحف المدينة؟", ["الوقف الممنوع، فإن اضطر القارئ إليه أعاد ووصل", "الوقف اللازم لئلا يُوهم معنى فاسدًا", "الوقف الجائز جوازًا مستوي الطرفين", "جواز الوقف على أحد الموضعين لا كليهما"], "علامة «لا» للوقف الممنوع لتعلق ما بعدها بها، فإن وقف القارئ اضطرارًا ابتدأ بالكلمة نفسها أو بما قبلها."] },

  { id: "tjm-080", s: "tajweed", g: 2, d: 2, t: ["waqf-signs", "muanaqa"], src: "Madina Muṣḥaf (King Fahd Complex), explanatory note on the stop signs",
    en: ["What does the sign of three dots appearing at two nearby places (muʿānaqa) mean?", ["One may stop at either place, but not at both", "One must stop at both places", "One may stop at neither place", "One stops at the first place in prayer and at the second outside it"], "Taʿānuq al-waqf (muʿānaqa) means that each of the two places is a valid stop on its own; stopping at one requires passing the other. Stopping at both would cut a phrase off from both sides."],
    de: ["Was bedeutet das Zeichen aus drei Punkten an zwei nahen Stellen (Muʿānaqa)?", ["Man darf an einer der beiden Stellen anhalten, aber nicht an beiden", "Man muss an beiden Stellen anhalten", "Man darf an keiner der beiden Stellen anhalten", "Man hält im Gebet an der ersten, außerhalb an der zweiten Stelle"], "Taʿānuq al-Waqf (Muʿānaqa) bedeutet, dass jede der beiden Stellen für sich ein gültiger Haltepunkt ist; hält man an einer, geht man über die andere hinweg. An beiden anzuhalten würde einen Ausdruck von beiden Seiten abtrennen."],
    ar: ["ما معنى علامة النقاط الثلاث في موضعين متقاربين (تعانق الوقف)؟", ["يجوز الوقف على أحد الموضعين لا على كليهما", "يجب الوقف على الموضعين كليهما", "لا يجوز الوقف على أيٍّ منهما", "يوقف على الأول في الصلاة وعلى الثاني خارجها"], "تعانق الوقف أن يكون كلٌّ من الموضعين محلًّا للوقف، فإذا وُقف على أحدهما لم يصح الوقف على الآخر؛ لأن الوقف عليهما معًا يقطع الكلمة التي بينهما عن الطرفين."] },

  // ---------- Stopping on word endings ----------
  { id: "tjm-081", s: "tajweed", g: 1, d: 1, t: ["waqf-endings", "taa-marbuta"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on stopping according to the rasm",
    en: ["How is a word ending in tāʾ marbūṭa (round tāʾ) pronounced when it is stopped on?", ["With a hāʾ sākina", "With a tāʾ sākina", "With an alif", "With the vowel shortened, but kept"], "Tāʾ marbūṭa becomes a hāʾ with sukūn in waqf. In continuous reading it is pronounced as tāʾ with its vowel."],
    de: ["Wie wird ein Wort mit Tāʾ marbūṭa (rundem Tāʾ) beim Anhalten gesprochen?", ["Mit einem Hāʾ sākina", "Mit einem Tāʾ sākina", "Mit einem Alif", "Mit verkürztem, aber erhaltenem Vokal"], "Tāʾ marbūṭa wird beim Anhalten zu einem Hāʾ mit Sukūn. Beim Weiterlesen wird es als Tāʾ mit seinem Vokal gesprochen."],
    ar: ["كيف يُنطق آخر الكلمة المختومة بتاء مربوطة عند الوقف عليها؟", ["هاءً ساكنة", "تاءً ساكنة", "ألفًا", "بحركة مختلسة"], "تُبدل التاء المربوطة عند الوقف هاءً ساكنة، وتُنطق في الوصل تاءً متحركة."] },

  { id: "tjm-082", s: "tajweed", g: 1, d: 1, t: ["waqf-endings", "tanwin-fath"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on waqf",
    en: ["How is a tanwīn with fatḥa (not on a tāʾ marbūṭa) treated when stopped on?", ["It is replaced by an alif", "It is dropped and the letter takes sukūn", "The nūn sound is kept with sukūn", "It is replaced by a hāʾ sākina"], "Tanwīn fatḥ turns into an alif of two counts in waqf (ibdāl). Tanwīn with ḍamma or kasra, by contrast, is dropped and the letter takes sukūn."],
    de: ["Wie wird ein Tanwīn mit Fatḥa (nicht auf Tāʾ marbūṭa) beim Anhalten behandelt?", ["Es wird durch ein Alif ersetzt", "Es fällt weg und der Buchstabe erhält Sukūn", "Der Nūn-Laut bleibt mit Sukūn erhalten", "Es wird durch ein Hāʾ sākina ersetzt"], "Tanwīn mit Fatḥa wird beim Anhalten zu einem Alif von zwei Zählzeiten (Ibdāl). Tanwīn mit Ḍamma oder Kasra fällt dagegen weg und der Buchstabe erhält Sukūn."],
    ar: ["كيف يُعامل تنوين الفتح (في غير التاء المربوطة) عند الوقف؟", ["يُبدل ألفًا", "يُحذف ويُسكَّن الحرف", "يبقى صوت النون ساكنًا", "يُبدل هاءً ساكنة"], "يُبدل تنوين النصب عند الوقف ألفًا تُمد حركتين، أما تنوين الرفع والجر فيُحذف ويُسكَّن الحرف."] },

  { id: "tjm-083", s: "tajweed", g: 2, d: 3, t: ["waqf-endings", "rawm-ishmam"], src: "al-Shāṭibī, Ḥirz al-Amānī, ch. on stopping with rawm and ishmām",
    en: ["What is rawm when stopping on a word?", ["Pronouncing part of the final vowel, about a third, with a faint voice", "Rounding the lips after the sukūn without any sound", "Replacing the final vowel with a full sukūn", "Lengthening the final vowel into a madd letter"], "Rawm lets a weak part of the vowel be heard so that its kind is recognised; it is used with ḍamma and kasra. Rounding the lips without sound is ishmām."],
    de: ["Was ist Raum beim Anhalten auf einem Wort?", ["Einen Teil des Endvokals, etwa ein Drittel, mit schwacher Stimme sprechen", "Die Lippen nach dem Sukūn ohne Laut runden", "Den Endvokal durch ein volles Sukūn ersetzen", "Den Endvokal zu einem Dehnungsbuchstaben verlängern"], "Beim Raum wird ein schwacher Teil des Vokals hörbar, damit man seine Art erkennt; er wird bei Ḍamma und Kasra verwendet. Das lautlose Runden der Lippen ist Išmām."],
    ar: ["ما الرَّوم عند الوقف على الكلمة؟", ["الإتيان ببعض الحركة الأخيرة بصوت خفي يُقدَّر بثلثها", "ضم الشفتين بعد الإسكان من غير صوت", "إبدال الحركة الأخيرة بسكون محض", "مدّ الحركة الأخيرة حتى تصير حرف مد"], "الروم النطق ببعض الحركة بصوت ضعيف يسمعه القريب، ويكون في المضموم والمكسور، أما ضم الشفتين بلا صوت فهو الإشمام."] },

  { id: "tjm-084", s: "tajweed", g: 2, d: 3, t: ["waqf-endings", "rawm-ishmam"], src: "al-Shāṭibī, Ḥirz al-Amānī, ch. on stopping with rawm and ishmām",
    en: ["What is ishmām when stopping on a word, and with which vowel is it used?", ["Rounding the lips right after the sukūn without sound; only with ḍamma", "Pronouncing a third of the vowel faintly; with ḍamma and kasra", "Rounding the lips with a faint sound; with every vowel", "Mixing the vowel with a slight kasra; only with fatḥa"], "Ishmām is seen, not heard: the lips round just after the final letter is made sākin, pointing to the ḍamma. It is not used with kasra or fatḥa."],
    de: ["Was ist Išmām beim Anhalten, und bei welchem Vokal wird es verwendet?", ["Die Lippen gleich nach dem Sukūn lautlos runden; nur bei Ḍamma", "Ein Drittel des Vokals leise sprechen; bei Ḍamma und Kasra", "Die Lippen mit leisem Laut runden; bei jedem Vokal", "Den Vokal mit einer leichten Kasra mischen; nur bei Fatḥa"], "Išmām sieht man, hört es aber nicht: Die Lippen runden sich, gleich nachdem der Endbuchstabe sākin gemacht wurde, als Hinweis auf die Ḍamma. Bei Kasra und Fatḥa wird es nicht angewendet."],
    ar: ["ما الإشمام عند الوقف، ومع أيِّ حركة يكون؟", ["ضم الشفتين عقب الإسكان من غير صوت، ولا يكون إلا في المضموم", "الإتيان بثلث الحركة بصوت خفي، ويكون في المضموم والمكسور", "ضم الشفتين مع صوت خفي، ويكون في كل حركة", "خلط الحركة بشيء من الكسر، ولا يكون إلا في المفتوح"], "الإشمام يُرى ولا يُسمع: تُضم الشفتان بُعيد إسكان الحرف إشارةً إلى الضمة، ولا يدخل المكسور ولا المفتوح."] },

  { id: "tjm-085", s: "tajweed", g: 3, d: 4, t: ["waqf-endings", "rawm-ishmam", "taa-marbuta"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on rawm and ishmām",
    en: ["Which of these word endings allows neither rawm nor ishmām when stopped on?", ["A tāʾ marbūṭa, which is read as hāʾ at the stop", "A final letter with ḍamma", "A final letter with ḍammatān", "A final letter with kasra"], "Rawm and ishmām point to the vowel of the letter actually stopped on. A tāʾ marbūṭa becomes a hāʾ that never had a vowel, so there is nothing to point to. Ḍamma allows both, kasra allows rawm."],
    de: ["Welches dieser Wortenden erlaubt beim Anhalten weder Raum noch Išmām?", ["Ein Tāʾ marbūṭa, das beim Anhalten als Hāʾ gelesen wird", "Ein Endbuchstabe mit Ḍamma", "Ein Endbuchstabe mit doppelter Ḍamma", "Ein Endbuchstabe mit Kasra"], "Raum und Išmām weisen auf den Vokal des Buchstabens hin, auf dem man anhält. Ein Tāʾ marbūṭa wird zu einem Hāʾ, das nie einen Vokal hatte, also gibt es nichts, worauf man hinweisen könnte. Ḍamma erlaubt beides, Kasra den Raum."],
    ar: ["أيُّ الأواخر الآتية لا يدخلها روم ولا إشمام عند الوقف؟", ["التاء المربوطة الموقوف عليها بالهاء", "الحرف الأخير المضموم", "الحرف الأخير المنوَّن بالضم", "الحرف الأخير المكسور"], "الروم والإشمام إشارة إلى حركة الحرف الموقوف عليه، والتاء المربوطة يُوقف عليها بهاء لم تكن متحركة فلا إشارة. أما المضموم فيدخله الأمران، والمكسور يدخله الروم."] },

  { id: "tjm-086", s: "tajweed", g: 4, d: 5, t: ["waqf-endings", "rawm-ishmam"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on rawm and ishmām",
    en: ["Why do the qurrāʾ not use rawm on a final fatḥa?", ["Because fatḥa is light: once part of it is uttered, all of it comes out", "Because fatḥa at the end of a word always turns into an alif", "Because rawm is only allowed on a tāʾ marbūṭa", "Because the lips cannot round for a fatḥa"], "Ibn al-Jazarī explains that the reciters did not apply rawm to fatḥa because of its lightness: a part of it cannot be separated from the whole. Lip rounding concerns ishmām, which is limited to ḍamma."],
    de: ["Warum wenden die Rezitatoren keinen Raum auf eine End-Fatḥa an?", ["Weil die Fatḥa leicht ist: Spricht man einen Teil, kommt sie ganz heraus", "Weil eine Fatḥa am Wortende immer zu Alif wird", "Weil Raum nur bei Tāʾ marbūṭa erlaubt ist", "Weil sich die Lippen für eine Fatḥa nicht runden können"], "Ibn al-Ǧazarī erklärt, dass die Rezitatoren wegen der Leichtigkeit der Fatḥa keinen Raum anwenden: Ein Teil lässt sich nicht vom Ganzen trennen. Das Lippenrunden betrifft das Išmām, das auf Ḍamma beschränkt ist."],
    ar: ["لماذا لم يستعمل القراء الروم في الفتحة الأخيرة؟", ["لخفة الفتحة، فإذا خرج بعضها خرج سائرها", "لأن الفتحة في آخر الكلمة تُبدل ألفًا دائمًا", "لأن الروم لا يكون إلا في التاء المربوطة", "لأن الشفتين لا تنضمان مع الفتحة"], "ذكر ابن الجزري أن القراء لم يرُوموا المفتوح لخفة الفتحة، فلا يمكن الإتيان ببعضها دون كلها. أما ضم الشفتين فمتعلق بالإشمام وهو خاص بالمضموم."] },

  { id: "tjm-087", s: "tajweed", g: 3, d: 4, t: ["waqf-endings", "tanwin-fath"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on waqf according to the rasm",
    en: ["How do the reciters in the riwāya of Ḥafṣ stop on the particle idhan, written with tanwīn fatḥ?", ["With an alif, like any tanwīn fatḥ", "With a nūn sākina, keeping the tanwīn as nūn", "With sukūn on the dhāl and no alif", "With a hāʾ sākina, like a tāʾ marbūṭa"], "Idhan is written in the muṣḥaf with an alif carrying tanwīn, and the reciters stop on it with an alif. The written form supports this stop."],
    de: ["Wie halten die Rezitatoren in der Überlieferung von Ḥafṣ auf der Partikel iḏan an, die mit Tanwīn Fatḥ geschrieben ist?", ["Mit einem Alif, wie bei jedem Tanwīn Fatḥ", "Mit einem Nūn sākina, das Tanwīn bleibt als Nūn", "Mit Sukūn auf dem Ḏāl und ohne Alif", "Mit einem Hāʾ sākina, wie bei Tāʾ marbūṭa"], "Iḏan ist im Muṣḥaf mit einem Alif mit Tanwīn geschrieben, und die Rezitatoren halten darauf mit einem Alif an. Die Schreibung stützt dieses Anhalten."],
    ar: ["كيف يقف القراء في رواية حفص على «إذًا» المرسومة بتنوين الفتح؟", ["بالألف كسائر تنوين النصب", "بنون ساكنة إبقاءً للتنوين", "بإسكان الذال من غير ألف", "بهاء ساكنة كالتاء المربوطة"], "رُسمت «إذًا» في المصحف بألف منونة، ويوقف عليها بالألف إبدالًا للتنوين، والرسم يؤيد ذلك."] },
];
